(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-streaming-serving-slo"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-1\">一 · 一次没有报警的 SLO 塌方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-2\">二 · 问题的结构：两个阶段，两种资源画像</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-3\">三 · 机制骨架：拆队列、连续批、微批解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-4\">四 · 适用边界：什么时候它不解决问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-5\">五 · 失败模式：降级太晚与队列倒挂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-6\">六 · 当静态批处理把 SLO 撕成两半：失效现场与适用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-7\">七 · 请求到达：画像估算与入队代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-8\">八 · 采样队列：紧迫度排序与动态批组合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-9\">九 · 采样完成到 latent 入队：跨阶段解耦的搬运代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-10\">十 · VAE 解码队列：微批并行与流式返回</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-11\">十一 · 监控回路：队列深度、利用率与配比调整</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-12\">十二 · 降级与准入反馈：违约风险高的处置路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-13\">十三 · 紧迫度排序的边界：画像漂移与降级阶梯的连锁失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-14\">十四 · SLO 可行域的形式化与逐项含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-15\">十五 · 紧迫度公式的推导与画像依赖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-16\">十六 · 组批的显存预算约束与可实现伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-17\">十七 · 两阶段流水的时延分解与 latent 队列代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-18\">十八 · 降级阶梯的触发条件与准入反馈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-19\">十九 · 公式到系统的映射与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-20\">二十 · 失效边界：画像漂移、降级滞后与短请求的固定开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-21\">二十一 · 负载配方的四个维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-22\">二十二 · 适合的请求形态：异构但有界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-23\">二十三 · 长度分布与批大小的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-24\">二十四 · 并发形态：稳态与突增的分界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-25\">二十五 · 负载不对时的三种失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-26\">二十六 · 配方与部署配比的联合标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-27\">二十七 · 硬件档位：按峰值并发与单请求显存画像定档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-28\">二十八 · 并行拓扑：采样与 VAE 分卡组、分并行轴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-29\">二十九 · 量化方案：采样激活与 VAE 输入分别定精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-30\">三十 · KV 与 latent 策略：按请求隔离、结束即回收</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-31\">三十一 · 调度参数：batch 上限、紧迫度阈值与降级阶梯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-32\">三十二 · 可复现的配置思路：先画像、再分档、后闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-33\">三十三 · 显存账本：谁在占用，谁在等</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-34\">三十四 · 带宽与通信：latent 搬运的隐性税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-35\">三十五 · 功耗与时钟：持续高占用的降频陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-36\">三十六 · 尾延迟：SLO 守门在长尾上的失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-37\">三十七 · 规模上去以后哪里先崩：崩序与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-38\">三十八 · 吞吐的边际收益与调度开销占比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-39\">三十九 · 规模拐点：先崩在队列内存与画像失准，而非算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-40\">四十 · 画像失准：紧迫度排序的静默失真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-41\">四十一 · OOM 与批抖动：显存预算的两种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-42\">四十二 · 路由不均与 latent 队列积压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-43\">四十三 · 尾延迟尖刺：降级触发时机的诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-44\">四十四 · 监控面与回滚路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-45\">四十五 · 诊断顺序与工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-46\">四十六 · 画像漂移与队列反压：这套调度的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-47\">四十七 · 对照轴：先分清&quot;改算法&quot;与&quot;改调度&quot;</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-48\">四十八 · 决策表：按负载形态选主算法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-49\">四十九 · 判据公式：什么条件下解耦才划算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-50\">五十 · 与预填解码分离的取舍：切在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-51\">五十一 · 与请求内算法的组合顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-streaming-serving-slo-sec-52\">五十二 · 规模上限与重标定触发条件</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:563px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 563.4 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求到达后按分辨率/时长/步数估算显存与时间，进入采样队列。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">调度器按SLO紧迫度与显存预算把请求组成采样batch，连续批处理在步间插…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样完成的latent进入VAE解码队列，按帧/块微批并行解码并流式返回。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">监控各阶段队列深度与GPU利用率，动态调整batch上限与阶段资源配比。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"481.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">SLO违约风险高时降级（减步/降分辨率/跳帧）并反馈给准入控制。</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-streaming-serving-slo-sec-1\">一 · 一次没有报警的 SLO 塌方</h3>\n<p>某在线流式视频服务在晚高峰出现了一次典型的“无声故障”：GPU 利用率曲线看起来健康，采样阶段长期维持在较高占用，但客户端侧的首帧时延与帧间隔双双越线，且违约请求沿着队列向后扩散。事后复盘发现，根因不在任何单请求的采样算法，而在服务层的批组织方式——调度器把采样阶段与 VAE 解码阶段塞进同一个静态批，批大小按采样阶段的显存占用一次性锁定。于是一批请求必须等最慢的那条完成全部采样步，才能整体进入 VAE 解码；VAE 解码期间采样单元空转，采样队列却在持续积压。当一批里混入高分辨率长时长请求时，整批的首帧时延被这条请求拖长，帧间隔也因为 VAE 只能整批解码而出现规律性抖动。</p>\n<p>这个案例的教训是：流式视频生成的 SLO 不是单一指标，而是三项约束的合取。写成判定式即</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{ok}}\\iff T_{\\text{first}}\\le D_{\\text{first}}\\ \\wedge\\ \\max_f(T_{f+1}-T_f)\\le D_{\\text{frame}},\\quad \\text{throughput}=\\frac{\\sum_r \\mathbb{1}[\\text{SLO}_r]}{T_{\\text{window}}}$$</div>\n<p>注意吞吐的定义：分子是满足 SLO 的请求数，而不是完成的请求数。静态批处理可以把完成数做得很高，却把分子做小——因为一批里只要有一条请求拖尾，整批的帧间隔与首帧时延一起失效。这就是本算法要解决的具体推理问题：<strong>在多请求并发下，让采样阶段与 VAE 解码阶段各自按自己的资源特征被批处理，从而同时守住首帧时延、帧间隔与端到端时长三类约束。</strong></p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-2\">二 · 问题的结构：两个阶段，两种资源画像</h3>\n<p>DiT 采样阶段是计算密集、显存带宽密集且步间同步频繁的循环：每一步都要跑完整的时空注意力与前馈，激活显存随分辨率与帧数增长，步与步之间存在天然的插入点。VAE 解码阶段则是另一副面孔：它按帧或按块推进，单块的计算量相对固定，瓶颈更多落在显存带宽与解码并行度上，且输出可以流式返回，天然适合微批并行。把两者绑在同一批里，等于强迫一个以步为节拍的计算阶段去等待一个以块为节拍的解码阶段，阶段切换处的 GPU 空转是结构性的，不是调参能消除的。</p>\n<p>更麻烦的是请求异构。线上流量是混合分辨率、混合时长、混合步数的：一条 720p、数秒、多步的请求与一条低分辨率短请求，显存画像可能差出一个量级。静态批大小若按峰值显存锁定，低负载时浪费，高负载时要么拒绝请求要么违约；若按均值锁定，峰值请求一进来就把整批拖垮。因此批大小必须由显存预算与 SLO 紧迫度共同决定，而不是一个固定值——这正是动态批组合要解决的问题，也是它与静态批处理的本质分野。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-3\">三 · 机制骨架：拆队列、连续批、微批解码</h3>\n<p>算法不改变单请求的采样或解码算法，只在服务层做三件事：阶段拆分、动态批组合、降级守门。请求到达后先按分辨率、时长、步数估算显存与时间，进入采样队列；调度器按 SLO 紧迫度与显存预算把请求组成采样 batch，连续批处理在采样步之间插入新请求，使采样单元不因批尾等待而空转；采样完成的 latent 不随原批一起等，而是进入独立的 VAE 解码队列，按帧或块做微批并行解码并流式返回；跨阶段用 latent 队列解耦，监控两阶段队列深度与 GPU 利用率，动态调整 batch 上限与阶段资源配比。</p>\n<p>紧迫度排序是这套机制的调度核心，可写为</p>\n<div class=\"formula\">$$u_i=\\frac{d_i-\\hat{t}_i^{\\text{rem}}}{\\hat{t}_i^{\\text{rem}}},\\quad \\text{priority}_i\\propto u_i$$</div>\n<p>其中 $d_i$ 是请求 $i$ 的截止时间，$\\hat{t}_i^{\\text{rem}}$ 是按当前模型与硬件画像估算的剩余执行时间。$u_i$ 越大越紧迫，调度器优先把它并入下一批。这个式子的工程含义很直接：紧迫度不是绝对剩余时间，而是剩余时间相对于自身执行成本的比值——一条短请求即使截止时间近，只要剩余执行时间也短，就不该压过一条已经濒临违约的长请求。连续批处理在此之上的价值是，采样步之间的插入点让新到达的高紧迫请求不必等当前批结束，从而把首帧时延从“批周期”量级压到“步周期”量级。</p>\n<p>代价必须说清楚。两阶段队列与 latent 搬运增加显存与同步开销：latent 要在采样卡组与解码卡组之间传递，队列本身占用显存，跨阶段同步引入额外延迟。短请求下这笔固定开销占比高，调度与搬运成本可能超过解耦带来的收益。此外 SLO 估算依赖模型与硬件画像，跨模型或跨 Blackwell SKU（B200 与 B300、GB200 与 GB300 NVL72 的显存与带宽档位不同）必须重新标定，否则 $\\hat{t}_i^{\\text{rem}}$ 失真会直接让紧迫度排序失效。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-4\">四 · 适用边界：什么时候它不解决问题</h3>\n<p>适用边界的第一条是多请求并发的在线流式服务。收益随请求异构度与负载波动增大：请求越异构，静态批的拖尾越严重；负载波动越大，固定批大小的浪费与违约越明显。反过来，极低并发下每个阶段只有一两条请求，解耦带来的队列与搬运开销无处摊薄，吞吐可能低于静态批处理；极短请求下同样如此，调度开销占比过高，阶段拆分的固定成本吃掉全部收益。</p>\n<p>第二条边界是它不解决单请求内部的算法问题。少步蒸馏采样、轨迹感知缓存复用、动态稀疏时空注意力、NVFP4/FP8 量化这些手段改变的是单请求的计算图与数值精度，本算法对此不做任何改动，只是在服务层决定这些请求如何被组合、何时被降级。同样，它不解决长视频单请求内部的分块重叠问题——那是单请求的分块策略，本算法关注的是多请求之间的资源配比与 SLO 守门。若把两者混为一谈，就会误以为拆了队列就能解决长视频的显存墙，实际并不会。</p>\n<p>第三条边界是规模上限由画像标定精度与队列内存决定。队列深度监控与 batch 上限调整都建立在画像可信的前提上；画像失准会让紧迫度排序失真，高优请求被低优请求挤占。跨 Blackwell SKU 部署时，采样与 VAE 可分配不同卡组或不同并行轴，但每一档硬件都要重新标定时间与显存画像，否则调度器的估算就是空中楼阁。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-5\">五 · 失败模式：降级太晚与队列倒挂</h3>\n<p>最危险的失败模式是降级触发过晚。降级阶梯是减步、降分辨率、跳帧，并反馈给准入控制；但这套阶梯只有在采样队列尚未深度积压时才有效。一旦采样阶段已经堆积大量请求，减步与降分辨率无法及时释放显存，违约会沿队列连锁扩散——前面一批的拖尾让后面一批的首帧时延越线，后面一批的越线又反过来加剧队列积压。触发过晚或阶梯过粗，等于把降级变成了事后记录而非事前守门。</p>\n<p>第二种失败模式是阶段倒挂：latent 队列积压使 VAE 解码阶段成为瓶颈，而采样阶段因为 batch 上限被压缩反而空转。此时 GPU 利用率曲线依旧好看，但两个阶段的实际吞吐不匹配，端到端时长越线。监控队列深度与 GPU 利用率的意义就在这里——只看总利用率会掩盖阶段间的失衡，必须分阶段看深度与占用，动态调整阶段资源配比。</p>\n<p>第三种是短请求下的负收益：两阶段队列与 latent 搬运的固定开销超过解耦收益，吞吐低于静态批处理。这不是算法错误，而是边界条件被越过；工程判断应当是给短请求设一条旁路，或在小规模部署时退回单阶段批处理，而不是强行套用拆队列结构。KV 策略上按请求隔离并在请求结束后立即回收，避免跨请求污染，这条在流式场景里尤其重要，因为请求生命周期短、复用窗口窄。</p>\n<p>把这三类失败模式放在一起看，本算法的工程判断可以归结为一句话：它是一层<strong>服务层的资源配比与守门机制</strong>，其正确性完全依赖于画像标定的可信度与降级触发的及时性；画像失准或降级滞后时，拆队列不但不救场，还会把单阶段的拖尾放大成两阶段的连锁违约。因此上线前必须用模型与硬件画像做 SLO 估算标定，按队列深度设 batch 上限，并把降级阶梯做成可观测、可回滚的显式状态，而不是藏在调度器里的隐式分支。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-6\">六 · 当静态批处理把 SLO 撕成两半：失效现场与适用边界</h3>\n<p>线上事故的形态往往不是单点崩溃，而是两类 SLO 同时被踩穿。设想一台 B200 节点同时承载混合分辨率、混合时长的流式请求：调度器按固定批大小把请求塞进 DiT 采样，采样阶段被长请求占满，短请求排在队尾；采样结束的 latent 又必须等整批一起进入 VAE 解码，于是首帧时延 <span class=\"inline-math\">T<sub>first</sub></span> 被拖过 <span class=\"inline-math\">D<sub>first</sub></span>，而后续帧间隔因 VAE 阶段整批同步解码出现周期性尖峰，<span class=\"inline-math\">max<sub>f</sub>(T<sub>f+1</sub>−T<sub>f</sub>)</span> 越过 <span class=\"inline-math\">D<sub>frame</sub></span>。判据写出来就是 <span class=\"formula\">$$\\text{SLO}_{\\text{ok}}\\iff T_{\\text{first}}\\le D_{\\text{first}}\\ \\wedge\\ \\max_f(T_{f+1}-T_f)\\le D_{\\text{frame}}$$</span> 事故的根因不在单个算子，而在采样与 VAE 的资源特征被强行绑在同一批里：采样是长时高占用、步间可插入的连续负载，VAE 是短时突发、按帧/块可切分的微批负载，静态批处理让 GPU 在阶段切换处空转，空转的时间又直接折算成帧间隔违约。</p>\n<p>这套阶段解耦调度解决的正是上述多请求并发下的 SLO 守门问题：把请求拆成采样队列与 VAE 解码队列，按 SLO 紧迫度与显存预算动态组批，跨阶段用 latent 队列解耦，采样走连续批处理、VAE 走微批并行。紧迫度用剩余时间画像归一化，<span class=\"formula\">$$u_i=\\frac{d_i-\\hat{t}_i^{\\text{rem}}}{\\hat{t}_i^{\\text{rem}}},\\quad \\text{priority}_i\\propto u_i$$</span> 调度器优先把 <span class=\"inline-math\">u<sub>i</sub></span> 大的请求并入下一批。但它不改变单请求的采样或解码算法，也不替代单请求内的分块重叠；它只在服务层做拆分、组批与降级。因此它不解决单请求本身的算子效率问题，也不解决模型精度问题——NVFP4/FP8 量化、tcgen05 与 TMEM 的算子收益属于别的层面，这里只用一句话指路。</p>\n<p>边界由三类代价划出。其一是固定开销：两阶段队列与 latent 搬运增加显存与同步成本，极短请求或极低并发下，调度与搬运的固定成本可能超过收益，吞吐反而低于静态批处理。其二是画像依赖：SLO 估算建立在模型与硬件画像上，跨模型或跨 Blackwell SKU（B200 与 B300、GB200 与 GB300 NVL72 的显存与带宽档位不同）未重新标定时，<span class=\"inline-math\">t̂<sub>i</sub><sup>rem</sup></span> 偏差会让紧迫度排序失真，高优请求被低优挤占。其三是降级阶梯的粒度：触发过晚或阶梯过粗（减步、降分辨率、跳帧三档跨度过大）时，采样阶段已积压大量请求，降级无法及时释放显存，违约沿队列连锁扩散；反过来，latent 队列积压会让 VAE 成为瓶颈而采样空转，此时收益随请求异构度与负载波动增大这一前提已被破坏。适用判断可以压缩成一张小表：</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>收益方向</th><th>失效风险</th></tr></thead><tbody><tr><td>请求异构度高、负载波动大</td><td>阶段独立组批减少空转</td><td>画像失准使排序失真</td></tr><tr><td>中长请求、并发充足</td><td>连续批处理守住帧间隔</td><td>latent 搬运显存开销</td></tr><tr><td>极短请求或极低并发</td><td>—</td><td>固定开销吃掉吞吐</td></tr><tr><td>跨 SKU 未重标定</td><td>—</td><td>降级过晚、连锁违约</td></tr></tbody></table>\n<p>工程判断落在准入侧：把画像标定精度与队列内存当作规模上限，用队列深度设 batch 上限，把降级阶梯与准入控制做成闭环，而不是等违约发生后再补救；吞吐按 <span class=\"formula\">$$\\text{throughput}=\\frac{\\sum_r \\mathbb{1}[\\text{SLO}_r]}{T_{\\text{window}}}$$</span> 计量，意味着任何一次连锁违约都会在窗口内被放大，调度器的第一优先级是守住 <span class=\"inline-math\">u<sub>i</sub></span> 排序的可信度，而非把 GPU 利用率推到满格。</p>\n<h3 id=\"alg-streaming-serving-slo-sec-7\">七 · 请求到达：画像估算与入队代价</h3>\n<p>请求进入服务层的第一件事不是分配 GPU，而是把请求参数翻译成资源画像。输入是三元组（分辨率、时长、步数）以及可选的精度档位（FP8/NVFP4），输出是两项估算：单请求显存占用 $\\hat{m}_i$ 与端到端执行时间 $\\hat{t}_i$。显存估算要覆盖采样阶段的激活峰值、latent 缓冲、以及 VAE 解码阶段的帧块工作集；时间估算则按采样步数与 VAE 解码块数分解，分别乘以当前硬件画像下的单步、单块耗时系数。这一步的代价是纯 CPU 侧的查表与插值，单请求在微秒到毫秒量级，但它决定了后续所有批组合的正确性。</p>\n<p>画像失准是本步骤的核心风险。跨模型或跨 Blackwell SKU（SM100 与 SM103 的 SM 数量、TMEM 容量、HBM 带宽档位不同）未重新标定时，$\\hat{t}_i$ 的系统性偏差会直接污染紧迫度排序。工程上的做法是把画像做成可版本化的表，按（模型、SKU、精度档、并行拓扑）四元组索引，服务启动时做一次小规模探针校准，而不是把系数硬编码进调度器。入队后请求获得一个截止时间 $d_i$，它由首帧时延上限与帧间隔上限共同推导，是后续紧迫度计算的锚点。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-8\">八 · 采样队列：紧迫度排序与动态批组合</h3>\n<p>采样队列的调度器在每个批组合窗口做一次决策：从队列中挑选请求组成采样 batch。排序键是紧迫度</p>\n<div class=\"formula\">$$u_i=\\frac{d_i-\\hat{t}_i^{\\text{rem}}}{\\hat{t}_i^{\\text{rem}}},\\quad \\text{priority}_i\\propto u_i$$</div>\n<p>其中 $\\hat{t}_i^{\\text{rem}}$ 是按当前画像估算的剩余执行时间。$u_i$ 越大表示剩余时间相对截止时间越紧张，调度器优先将其并入下一批。批大小不是固定值，而是由显存预算与紧迫度共同约束：显存预算给出上限 $B_{\\max}$，紧迫度分布决定实际取值——当队列头部集中了大量高 $u_i$ 请求时，宁可缩小 batch 以保证它们尽快启动，而不是为了吞吐把 batch 撑满。</p>\n<p>这里的代价结构值得拆开看。增大 batch 提升采样阶段的 GPU 占用率与吞吐，但会拉长单批的执行时间，直接推高批内每个请求的首帧时延；缩小 batch 降低首帧时延却浪费算力。连续批处理是调和这一矛盾的手段：在采样步与步之间插入新到达的请求，使 batch 成员在时间上滚动更替，而不必等整批采样结束才接纳新请求。代价是每步都要做一次成员变更与 KV/latent 缓冲的重排，步间同步开销随插入频率上升。对 DiT 采样而言，步间插入意味着新请求的 latent 要与已有请求的 latent 在 batch 维度拼接，显存布局需预留可增长的槽位，否则重排会触发拷贝。</p>\n<p>具体例子：一个 720p、5 秒、30 步的请求与若干 480p、2 秒、20 步的短请求同时在队列中。长请求的 $\\hat{t}_i^{\\text{rem}}$ 大，若其截止时间宽松，$u_i$ 可能反而低于短请求；调度器会把短请求优先并入当前 batch 的空槽，长请求则等待下一个组合窗口。若长请求的 $d_i$ 逼近，$u_i$ 抬升，它会挤占槽位，短请求被推迟——这正是画像失准时排序失真的典型场景。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-9\">九 · 采样完成到 latent 入队：跨阶段解耦的搬运代价</h3>\n<p>采样阶段产出的是 latent 张量，它不是可直接显示的帧。请求从采样队列迁移到 VAE 解码队列的动作，是把 latent 写入一个跨阶段队列，并附带元数据（帧数、分辨率、解码块划分、截止时间）。输入是采样输出的 latent 与其显存句柄，输出是 VAE 队列中的一个待解码条目。解耦的意义在于两个阶段的资源特征不同：采样是计算密集、以 MMA 吞吐为瓶颈；VAE 解码是访存密集、以帧块并行度为瓶颈。若串行绑定在同一 batch 内，采样结束到 VAE 开始之间的阶段切换会让 GPU 出现空转窗口。</p>\n<p>代价集中在显存与同步。latent 队列本身占用显存，队列深度越大，驻留的 latent 越多，显存预算被挤占得越厉害；跨阶段搬运若涉及不同卡组（采样与 VAE 分配在不同 GPU 上），还要付出 NVLink 传输与同步原语的开销。短请求下这笔固定成本占比突出：一个 2 秒、20 步的请求，其采样时间本就不长，latent 搬运与队列同步可能吃掉可观的比例，使两阶段解耦的收益被抵消。工程判断是给队列设深度上限并按请求时长分级——短请求走更浅的队列甚至直通路径，长请求才享受完整的两阶段流水。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-10\">十 · VAE 解码队列：微批并行与流式返回</h3>\n<p>VAE 队列的调度单位不是整个请求，而是帧或块。输入是 latent 条目，输出是按块解码出的帧，逐块流式返回给客户端。微批并行的含义是把多个请求的解码块拼成一个小 batch 一起送进 VAE，块大小与 batch 大小共同决定单次解码的显存工作集与延迟。与采样阶段的连续批处理不同，VAE 阶段追求的是降低单帧等待：首帧必须尽快出来以满足 $T_{\\text{first}}\\le D_{\\text{first}}$，后续帧则要满足帧间隔约束 $\\max_f(T_{f+1}-T_f)\\le D_{\\text{frame}}$。</p>\n<p>帧间隔 SLO 对 VAE 调度提出了节奏性要求。解码不能一次性把整个请求解完再返回，否则首帧时延被拉长；也不能解得太慢，否则帧间隔违约。调度器需要按 $D_{\\text{frame}}$ 反推每块解码的时间预算，并据此决定微批的并发度。代价是显存：多个请求的解码块同时驻留，VAE 的中间激活叠加，显存峰值随微批并发度线性上升。若 latent 队列积压而 VAE 阶段吞吐不足，解码队列成为瓶颈，采样阶段反而空转——这是两阶段解耦最典型的失衡形态，监控必须同时看两个队列的深度比值而非单看某一个。</p>\n<p>具体例子：三个请求同时进入 VAE 队列，各自需要解码 120 帧。若按帧微批、每批 8 帧并行，首帧可在第一个微批完成时返回，后续帧按节奏补齐；若把三个请求的帧混在一个大批里，首帧要等整批解码，首帧时延直接违约。量化在此处的作用是压缩 VAE 输入与中间激活的位宽（FP8/NVFP4），降低访存压力，但它属于精度分配话题，此处只作为显存预算的一个调节旋钮。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-11\">十一 · 监控回路：队列深度、利用率与配比调整</h3>\n<p>调度器周期性采样两个阶段的队列深度与 GPU 利用率，输出是 batch 上限与阶段资源配比的调整量。输入是队列深度序列、SM 占用率、HBM 带宽利用率，输出是 $B_{\\max}$ 的新取值以及采样/VAE 卡组配比。判据是失衡信号：采样队列深而 VAE 队列浅，说明解码能力过剩，应把资源向采样倾斜；反之 latent 队列积压，说明 VAE 是瓶颈，需扩大解码微批并发或增配卡组。</p>\n<p>这一步的代价是调整本身的滞后性。配比调整涉及卡组重分配或并行轴切换，不是瞬时动作；在调整生效前，失衡仍在累积。因此监控回路必须与降级阶梯联动，而不是等配比调整到位才行动。另一个代价是画像依赖：利用率阈值与队列深度阈值的设定来自硬件画像，跨 SKU 未重新标定时阈值失配，监控会误判失衡方向。吞吐的度量在此处落地为</p>\n<div class=\"formula\">$$\\text{throughput}=\\frac{\\sum_r \\mathbb{1}[\\text{SLO}_r]}{T_{\\text{window}}}$$</div>\n<p>即窗口内满足全部三项 SLO 的请求数除以窗口时长。注意分子是 SLO 达标计数而非完成计数——一个完成了但帧间隔违约的请求不计入吞吐，这使监控回路不能只看 GPU 利用率，必须把 SLO 达标率作为一等指标。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-12\">十二 · 降级与准入反馈：违约风险高的处置路径</h3>\n<p>当监控判定某请求的 SLO 违约风险高（$u_i$ 超过阈值且剩余时间不足以按当前配置完成），调度器触发降级阶梯：减步、降分辨率、跳帧，按代价从低到高逐级尝试。输入是请求的当前进度与剩余预算，输出是修改后的执行计划。减步直接缩短采样时间，代价是生成质量下降；降分辨率同时降低采样与 VAE 的显存与时间开销，代价最显著；跳帧减少解码块数，直接缓解 VAE 瓶颈但破坏帧连续性。降级的选择要按当前瓶颈所在阶段来定——采样瓶颈优先减步，VAE 瓶颈优先跳帧，而不是机械地按固定顺序执行。</p>\n<p>降级动作反馈给准入控制：当降级触发率上升，说明系统已进入过载区，准入控制应收紧新请求的接纳速率，避免队列继续膨胀。这里的失败模式是触发过晚或阶梯过粗：采样阶段已积压大量请求时，减步与降分辨率无法及时释放显存，违约沿队列连锁扩散——一个请求的降级释放的资源被新积压的请求立即吃掉，系统进入降级也救不回来的状态。工程上的防线是把降级阈值设在违约之前而非之后，并让阶梯足够细，使每次降级只释放刚好够用的资源而不是一次性砍掉大半质量。</p>\n<p>整个链路的顺序性决定了代价的叠加方式：画像估算的误差传播到紧迫度排序，排序误差传播到批组合，批组合的失衡传播到 latent 队列深度，队列积压最终表现为降级触发。因此校准画像表、给队列设深度上限、把降级阈值前移，这三件事是同一件事的三个切面——它们共同决定了两阶段解耦在负载波动下是守住 SLO 还是连锁违约。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-13\">十三 · 紧迫度排序的边界：画像漂移与降级阶梯的连锁失效</h3>\n<p>该机制真正脆弱的环节不在批组合本身，而在紧迫度公式的输入项。调度器按 <span class=\"formula\">$$u_i=\\frac{d_i-\\hat{t}_i^{\\text{rem}}}{\\hat{t}_i^{\\text{rem}}}$$</span> 排序，其中剩余执行时间 $\\hat{t}_i^{\\text{rem}}$ 完全来自模型与硬件画像。画像一旦失准，$u_i$ 的符号与量级都会失真：高估剩余时间会让紧迫请求被排到队尾，低估则让宽松请求抢占显存预算。跨 Blackwell SKU 部署时，SM100 与 SM103 的算力配比、TMEM 容量与显存带宽不同，采样步的实际耗时与 VAE 解码的帧吞吐必须重新标定；跨模型（不同 DiT 参数量、不同 latent 通道数）同理。未重标定的直接代价是采样 batch 的显存预算被错误请求占用，GPU 占用率看似饱和，但 SLO 满足率沿队列下滑——这是纯吞吐指标掩盖不了的失效。</p>\n<p>第二个边界是降级阶梯的粒度与时序。减步、降分辨率、跳帧三档若只在端到端剩余时间跌破阈值时触发，采样队列往往已积压数批请求，此时释放的显存不足以让后续批次立即成形，违约会从单个请求扩散为队列级连锁。可行的工程约束是把降级判定前移到准入侧：当采样队列深度超过按画像标定的上限、或 VAE 队列的 latent 积压超过单卡可容纳的块数时，直接对新到请求降档而非对在途请求降档，避免在途请求的帧间隔被二次破坏。代价是准入拒绝率上升，吞吐公式 <span class=\"formula\">$$\\text{throughput}=\\frac{\\sum_r \\mathbb{1}[\\text{SLO}_r]}{T_{\\text{window}}}$$</span> 的分子只计守门成功的请求，被降档但仍违约的请求不计入，因此降级必须与准入反馈成对出现，否则只是把违约从采样阶段搬到解码阶段。</p>\n<p>第三个边界是两阶段解耦的固定开销。latent 队列跨阶段搬运引入显存占用与同步点，短请求（低分辨率、少步数、短时长）下这部分开销与调度判定的成本占比过高，收益可能被抵消。判断标准是单请求的采样步耗时与 VAE 微批解码耗时之和是否显著大于一次 latent 入队/出队与批组合判定的开销；若否，静态批处理反而更省。下表给出该方案在不同负载形态下的适用性判断。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>阶段解耦收益</th><th>主要代价来源</th></tr></thead><tbody><tr><td>高异构、负载波动大</td><td>显著，采样与 VAE 各自满批</td><td>画像标定精度</td></tr><tr><td>同构长请求、稳定负载</td><td>有限，静态批已接近最优</td><td>latent 搬运与同步</td></tr><tr><td>极短请求、低并发</td><td>可能为负</td><td>调度与搬运固定成本</td></tr></tbody></table>\n<p>因此该方案的规模上限由画像标定精度与队列内存共同决定，而非由 GPU 峰值算力决定；工程上应把重标定作为跨 SKU、跨模型上线的前置步骤，并把队列深度上限与降级阶梯绑定为同一组可观测指标，避免采样空转而 VAE 成为瓶颈的隐性失效。</p>\n<h3 id=\"alg-streaming-serving-slo-sec-14\">十四 · SLO 可行域的形式化与逐项含义</h3>\n<p>把流式视频服务的质量承诺写成可判定的谓词，是调度器能够做决策的前提。给定请求 <em>r</em>，其 SLO 可行记为：</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{ok}}\\iff T_{\\text{first}}\\le D_{\\text{first}}\\ \\wedge\\ \\max_f(T_{f+1}-T_f)\\le D_{\\text{frame}},\\quad \\text{throughput}=\\frac{\\sum_r \\mathbb{1}[\\text{SLO}_r]}{T_{\\text{window}}}$$</div>\n<p>逐项拆开看：$T_{\\text{first}}$ 是从请求准入到第一帧可见的墙钟时间，$D_{\\text{first}}$ 是首帧预算；$T_f$ 是第 <em>f</em> 帧的交付时刻，帧间隔约束取所有相邻帧差的最大值，而不是平均值——这一点决定了调度器不能靠“平均帧率达标”蒙混，任何一次抖动都会让该请求判负。$\\mathbb{1}[\\text{SLO}_r]$ 是示性函数，吞吐因此不是帧数/秒，而是<strong>单位时间窗内满足全部约束的请求数</strong>。这个定义把吞吐与违约率绑定在一起：一个把 GPU 打满却让 30% 请求超帧间隔的策略，吞吐指标反而低于留出余量的保守策略。工程上这意味着调度目标不是最大化利用率，而是在利用率与守门率之间找可行点。</p>\n<p>推导的关键一步在于把“帧间隔”从端到端约束中剥离。端到端时长 $T_{\\text{last}}\\le D_{\\text{e2e}}$ 是累积约束，而帧间隔是逐帧的局部约束；前者可以由后者加上首帧时延推出上界（若每帧间隔都不超过 $D_{\\text{frame}}$，则 $T_{\\text{last}}\\le T_{\\text{first}}+(F-1)D_{\\text{frame}}$），所以调度器只需在每帧交付时检查局部条件，无需为端到端单独维护计时器。代价是：这个上界是充分而非必要条件，按它守门会偏保守，在长视频、多帧场景下会牺牲一部分可接纳并发。对 B200 单节点多卡部署而言，保守守门意味着采样 batch 上限被人为压低，SM 占用率下降，这是显存换确定性的典型取舍。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-15\">十五 · 紧迫度公式的推导与画像依赖</h3>\n<p>调度器要把有限显存预算分配给最该先跑的请求，需要一个可比较的标量。定义请求 <em>i</em> 的紧迫度：</p>\n<div class=\"formula\">$$u_i=\\frac{d_i-\\hat{t}_i^{\\text{rem}}}{\\hat{t}_i^{\\text{rem}}},\\quad \\text{priority}_i\\propto u_i$$</div>\n<p>$d_i$ 是截止时刻（由准入时刻加 $D_{\\text{first}}$ 或 $D_{\\text{e2e}}$ 得到），$\\hat{t}_i^{\\text{rem}}$ 是按当前模型/硬件画像估算的剩余执行时间。分子的含义是“还剩多少时间余量”，分母做归一化，使不同时长、不同步数的请求可比：一个剩 200 ms 余量、还需 1 s 的请求（$u=-0.8$）远比一个剩 2 s 余量、还需 10 s 的请求（$u=-0.8$ 相同）——注意这里两者相等，说明该式对绝对规模不敏感，这正是它作为排序键的优点，也是它的盲点：它无法区分“差一点就违约的小请求”和“差很多的大请求”，后者一旦违约代价更高。工程上常在此式外再乘一个按分辨率/时长分档的权重来补偿。</p>\n<p>推导的关键一步是把 $\\hat{t}_i^{\\text{rem}}$ 分解为阶段可加项：$\\hat{t}_i^{\\text{rem}}=\\hat{t}_i^{\\text{samp}}+\\hat{t}_i^{\\text{vae}}+\\hat{t}_i^{\\text{queue}}$，其中队列项随当前队列深度线性增长。这一步让紧迫度成为<strong>队列状态的函数</strong>而非静态常量，调度器每次组批都要重算。代价直接体现在画像标定上：$\\hat{t}^{\\text{samp}}$ 依赖步数、分辨率与 batch 内其他请求的干扰（连续批处理下新请求插入会拉长在跑请求的步时间），$\\hat{t}^{\\text{vae}}$ 依赖分块数与微批大小。跨 Blackwell SKU（B200 与 B300 的 SM 配比、显存带宽不同）或换模型后，未重新标定的画像会让 $u_i$ 排序失真，高优请求被低优请求挤占——这是该机制最典型的失败路径，且失效是静默的，指标上看不出异常直到违约率跳升。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-16\">十六 · 组批的显存预算约束与可实现伪代码</h3>\n<p>批大小不是固定值，而是显存预算与紧迫度的联合解。设请求 <em>i</em> 的采样显存画像为 $m_i^{\\text{samp}}$（激活、KV、latent 缓冲之和），VAE 阶段为 $m_i^{\\text{vae}}$，卡组可用显存为 $M$，则采样批 $\\mathcal{B}$ 的可行条件为 $\\sum_{i\\in\\mathcal{B}} m_i^{\\text{samp}}\\le M-\\Delta$，$\\Delta$ 是留给 latent 队列与临时缓冲的余量。组批是一个带优先级排序的背包：按 $u_i$ 降序贪心装入，装不下则跳过并尝试更小的请求——这保证紧迫请求优先获得显存，同时避免大请求饿死小请求之外的所有人。</p>\n<p>落到可实现层面，采样阶段的连续批处理循环可写成如下思路：每个采样步结束后，检查队列头部是否有新请求能在当前显存余量下并入；并入时为其分配独立的 KV 与 latent 区，步内不做跨请求的注意力混合；步末统一回收已完成请求的显存。伪代码层面：</p>\n<ul>\n<li>准入：估算 $m_i^{\\text{samp}},m_i^{\\text{vae}},\\hat{t}_i$，计算 $u_i$，入采样队列；若队列深度超阈值则拒绝或降级。</li>\n<li>组批：按 $u_i$ 降序贪心装入至显存上限，记录批内请求集合与预计步时间。</li>\n<li>步进：执行一步 DiT 采样；步末扫描队列，尝试插入新请求（显存允许且不使批内已有请求的预计剩余时间超过其截止）；回收已完成请求。</li>\n<li>交接：采样完成的 latent 压入 VAE 队列，携带该请求的帧间隔截止时刻。</li>\n<li>反馈：每步更新队列深度与 GPU 利用率，越界则调整批上限或触发降级阶梯。</li>\n</ul>\n<p>代价在这里非常具体：连续批处理插入新请求会拉长在跑请求的单步时间，因为新请求的激活要参与同一次 kernel 发射，SM 上的 warp 调度被摊薄；在 B200 上这表现为步时间的方差增大，而帧间隔约束取的是最大值，方差直接吃掉守门余量。短请求场景下，组批与插入的调度开销占单请求总时长的比例上升，固定成本可能超过解耦带来的收益。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-17\">十七 · 两阶段流水的时延分解与 latent 队列代价</h3>\n<p>把端到端时延写成阶段和，是判断瓶颈位置的唯一可靠手段：</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=\\underbrace{T_{\\text{adm}}+T_{\\text{wait}}^{\\text{samp}}}_{\\text{采样前}}+\\underbrace{\\sum_{s}\\tau_s^{\\text{samp}}}_{\\text{采样}}+\\underbrace{T_{\\text{wait}}^{\\text{vae}}}_{\\text{latent 排队}}+\\underbrace{\\sum_{b}\\tau_b^{\\text{vae}}}_{\\text{解码}}+\\underbrace{T_{\\text{ret}}}_{\\text{返回}}$$</div>\n<p>解耦的价值在于 $T_{\\text{wait}}^{\\text{samp}}$ 与 $T_{\\text{wait}}^{\\text{vae}}$ 可以独立压缩：采样队列按连续批处理保持高占用，VAE 队列按帧/块微批并行，两者不再互相等待对方的批边界。推导的关键一步是认识到 $\\tau_s^{\\text{samp}}$ 与 $\\tau_b^{\\text{vae}}$ 对 batch 大小的敏感度不同——采样阶段扩大 batch 摊薄权重读取带宽，收益接近线性直到算力饱和；VAE 阶段扩大微批主要摊薄 kernel 发射与同步开销，收益很快饱和。因此两阶段的最优批大小天然不同，静态批处理强制统一批大小，必然在其中一阶段留下空转或等待。</p>\n<p>代价落在 latent 队列上：跨阶段搬运 latent 要占显存（每个在途请求一份），队列积压时 VAE 阶段成为瓶颈而采样阶段空转——这是解耦架构最典型的失衡形态。工程判断是给 latent 队列设硬上限并按队列深度反压采样准入，而不是让采样无限超前。以混合分辨率请求为例：一批 720p 长时长请求采样完成后，latent 体积大、VAE 解码耗时长，若此时队列中又涌入大量短请求，VAE 队列深度会迅速抬高，采样侧即便有空闲显存也不应继续接纳，否则违约沿队列连锁扩散。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-18\">十八 · 降级阶梯的触发条件与准入反馈</h3>\n<p>降级不是拍脑袋，而是由紧迫度分布触发的确定性动作。设降级阈值为 $\\theta$，当采样队列中满足 $u_i&lt;\\theta$ 的请求占比超过某比例，或 latent 队列深度超过上限，则启动阶梯：先减步（采样步数下调，直接缩短 $\\sum_s\\tau_s^{\\text{samp}}$），再降分辨率（缩小 $m_i^{\\text{samp}}$ 与 $\\tau_b^{\\text{vae}}$），最后跳帧（放宽帧间隔约束的有效帧数）。阶梯的顺序按“单位降级量换取的时延收益”排序，减步的收益最直接且不改变输出尺寸，跳帧对观感损伤最大故置末。</p>\n<p>推导的关键一步是把降级收益写成可比较的量：减步 $\\delta$ 步带来的时延缩减约为 $\\delta\\cdot\\bar{\\tau}^{\\text{samp}}$，而降分辨率带来的显存释放约为 $\\alpha m_i^{\\text{samp}}$，两者量纲不同，调度器需按当前瓶颈（时间还是显存）选择阶梯入口。触发过晚或阶梯过粗是明确的失败模式：采样阶段已积压大量请求时，减步释放的显存不足以让新请求并入，违约沿队列扩散；阶梯只有“全降”和“不降”两档时，降级本身造成帧间隔抖动，反而触发更多违约。因此阶梯应是多档、细粒度、且每档执行后重新评估 $u_i$ 分布。</p>\n<p>准入反馈闭环是最后一块：降级发生后，调度器把当前可接纳并发上限回写给准入控制，新请求在入口处即被拒绝或排队到下一时间窗，避免降级期间继续注入负载。代价是准入拒绝会损失吞吐，但在 SLO 守门优先的服务契约下，拒绝一个注定违约的请求比接纳后违约更划算——前者不污染吞吐指标的分子。跨模型或跨 SKU 未重新标定时，降级阈值与阶梯收益都会失准，这是该闭环最需要运维纪律的地方。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-19\">十九 · 公式到系统的映射与工程判断</h3>\n<p>把上述公式串起来看，调度器的每次决策都在解一个约束优化：最大化 $\\sum_r\\mathbb{1}[\\text{SLO}_r]$，约束是显存预算、帧间隔上界与阶段资源配比。可实现的判断规则有三条。其一，帧间隔约束取最大值而非均值，意味着调度器应优化<strong>尾部步时间</strong>而非平均步时间，批内请求的步时间方差是比利用率更重要的观测量。其二，$u_i$ 的排序必须每步重算，静态优先级队列在连续批处理下会迅速失准，因为 $\\hat{t}^{\\text{rem}}$ 随队列深度变化。其三，两阶段的批上限应分别标定并分别设反压阈值，用一个全局 batch 上限同时管两阶段，等于把解耦退化成静态批处理。</p>\n<p>具体到一次组批决策：调度器读入队列，按 $u_i$ 降序贪心装入采样批至显存上限减 $\\Delta$，发射一步采样，步末用实测步时间更新 $\\hat{t}^{\\text{samp}}$ 的画像系数，再判断是否插入新请求；采样完成的 latent 带截止时刻入 VAE 队列，VAE 侧按帧微批并行并优先解码截止最近者。这套循环的固定开销在短请求下不可忽略，因此对极短请求应设一条旁路：低于某时长阈值的请求直接走单请求路径，不进入两阶段队列，避免调度开销吃掉全部收益。这是适用边界的工程表达——收益随请求异构度与负载波动增大，极低并发或极短请求下解耦反而是负收益。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-20\">二十 · 失效边界：画像漂移、降级滞后与短请求的固定开销</h3>\n<p>这套阶段解耦调度的正确性完全建立在剩余时间估计 $\\hat{t}_i^{\\text{rem}}$ 的可信度上。紧迫度 $u_i=(d_i-\\hat{t}_i^{\\text{rem}})/\\hat{t}_i^{\\text{rem}}$ 的排序在画像准确时是单调有效的，但它对误差的敏感度不对称：当 $\\hat{t}_i^{\\text{rem}}$ 被低估，调度器会把高优请求误判为宽松，让低优请求先占满显存预算，等到真实剩余时间暴露时已无法插队；当它被高估，则触发不必要的降级，把本可正常完成的请求减步降分辨率。跨 Blackwell SKU（B200 与 B300、GB200 与 GB300 NVL72）或跨模型未重新标定时，采样步耗时与 VAE 解码吞吐的画像偏差会直接污染这个比值，紧迫度排序失真，SLO 守门退化为随机抢占。工程上的判断是：画像必须按（模型, SKU, 分辨率档, 量化格式）四元组分别标定，并在运行期用实测步耗时做在线修正，而不是一次性离线标定后长期复用。</p>\n<p>降级阶梯的触发时机比阶梯本身更关键。设采样队列深度为 $Q_s$、VAE 队列深度为 $Q_v$，若降级只在 $Q_s$ 超过阈值后触发，此时显存已被在途 batch 占满，减步与降分辨率无法立即释放资源，违约沿队列连锁扩散——前一批的帧间隔违约会推迟后续请求的首帧时延。可实现的判据是把触发条件前移到“预测违约”而非“已违约”：当 $\\max_i u_i$ 超过阈值且 $Q_s$ 的增长率在连续若干调度周期内为正时即启动第一级降级，把减步作为最轻的一档，跳帧作为最重的一档，并同步收紧准入控制。代价是降级本身消耗调度周期与一次 latent 重排，短请求下这部分开销占比高。</p>\n<p>短请求与低并发是这套方案的收益反转区。两阶段队列、latent 在采样卡组与 VAE 卡组之间的搬运、跨阶段同步，构成一笔与请求时长无关的固定成本 $C_{\\text{fix}}$；单请求有效计算为 $T_{\\text{work}}$ 时，解耦带来的收益需满足 $C_{\\text{fix}} &lt; T_{\\text{work}}\\cdot\\eta$，其中 $\\eta$ 是静态批处理下的空转比例。极短请求（少步数、低分辨率、短时长）使 $T_{\\text{work}}$ 缩小而 $C_{\\text{fix}}$ 不变，吞吐反而低于静态批处理。因此准入侧应按估算时长设阈值，低于阈值的请求走单阶段合并路径，不进入两阶段队列。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>可观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>画像未按 SKU 重标定</td><td>紧迫度排序与实测完成顺序背离</td><td>高优请求被挤占，端到端 SLO 违约</td></tr><tr><td>降级触发滞后</td><td>$Q_s$ 连续增长且显存接近预算上限</td><td>减步无法释放显存，违约连锁扩散</td></tr><tr><td>短请求占比高</td><td>latent 搬运与同步时间占请求时长比例上升</td><td>吞吐低于静态批处理，GPU 利用率虚高</td></tr></tbody></table>\n<h3 id=\"alg-streaming-serving-slo-sec-21\">二十一 · 负载配方的四个维度</h3>\n<p>流式视频生成的请求不是同质的。一条请求至少携带四个变量：分辨率（决定每帧 latent 的空间尺寸与注意力矩阵规模）、时长（决定总帧数与端到端 SLO 的绝对量级）、采样步数（决定 DiT 前向次数，直接线性放大采样阶段耗时）、以及到达时刻的并发环境。负载配方就是这四个维度的联合分布。调度器在请求到达时按分辨率、时长、步数估算显存与时间，这个估算不是可选项——它是后续紧迫度排序与批组合的唯一输入。配方决定了估算误差的分布形态：当请求集中在单一分辨率、固定步数、相近时长时，画像标定一次即可覆盖绝大多数请求，估算残差小；当四个维度都离散时，画像需要覆盖的组合数爆炸，估算残差成为调度噪声的主要来源。</p>\n<p>从服务容量角度看，配方直接决定两件事：单请求显存画像的方差，以及采样阶段与 VAE 阶段负载的比值。前者影响 batch 上限能否被稳定打满，后者影响两个阶段卡组的资源配比是否会出现一侧长期空转。一个健康的配方应当让采样队列与 VAE 队列的深度在同一量级波动，而不是一侧持续积压、另一侧持续饥饿。</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{ok}}\\iff T_{\\text{first}}\\le D_{\\text{first}}\\ \\wedge\\ \\max_f(T_{f+1}-T_f)\\le D_{\\text{frame}},\\quad \\text{throughput}=\\frac{\\sum_r \\mathbb{1}[\\text{SLO}_r]}{T_{\\text{window}}}$$</div>\n<p>吞吐的定义里分子是窗口内满足 SLO 的请求计数，这意味着负载配方不只是性能问题，它直接进入吞吐的分母——不满足 SLO 的请求不计入吞吐，但它们消耗的 GPU 时间是实打实的。配方错配时，GPU 利用率可能很高而吞吐很低，这是流式视频服务最典型的隐性浪费。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-22\">二十二 · 适合的请求形态：异构但有界</h3>\n<p>这套调度机制收益最大的形态是“异构但有界”的混合负载：分辨率分布在两到三档、时长集中在少数几个档位、步数由少步蒸馏采样固定为小集合。异构度提供批组合的腾挪空间——当一条高分辨率长时长请求占据大量显存时，调度器可以用若干低分辨率短请求填补剩余显存预算，使采样 batch 的显存占用贴近上限而单步时间不显著拉长。有界性则保证画像标定的组合数可控，剩余时间估算的残差落在可接受范围。</p>\n<p>具体机制上，采样阶段用连续批处理在步间插入新请求：一条请求采样到第 k 步时，新到达的请求可以并入同一 batch 的后续步，而不必等当前 batch 全部完成。这要求 batch 内各请求的步数不必对齐——步数少的请求提前退出，空出的显存槽位立即被队列头部请求占据。VAE 阶段则按帧或块做微批并行，单帧解码的等待被压缩到微批粒度，流式返回的帧间隔由微批节奏而非整段解码时长决定。</p>\n<p>代价在于两阶段队列与 latent 搬运的固定开销。每条请求在采样完成后要把 latent 写入队列、由 VAE 阶段读出，这带来一次显存写入加一次显存读取，以及跨阶段的同步点。当请求的采样步数很少、时长很短时，这笔固定开销在单请求总耗时中的占比上升，连续批处理带来的占用率收益被抵消。工程判断是：配方中短请求占比越高，越需要把 latent 队列做成零拷贝的显存池引用而非数据搬运，否则调度开销会吃掉解耦的收益。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-23\">二十三 · 长度分布与批大小的耦合</h3>\n<p>批大小由显存预算与 SLO 紧迫度共同决定，而非固定值。显存预算给出上界：batch 内所有请求的采样激活、KV 或中间态、以及 latent 缓冲之和不得超过卡上可用显存。紧迫度给出下界约束：当队列头部请求的紧迫度 $u_i$ 很高时，调度器倾向于缩小 batch 以缩短单步时间，牺牲吞吐换首帧时延。这两者的拉扯在长度分布偏斜时最剧烈。</p>\n<div class=\"formula\">$$u_i=\\frac{d_i-\\hat{t}_i^{\\text{rem}}}{\\hat{t}_i^{\\text{rem}}},\\quad \\text{priority}_i\\propto u_i$$</div>\n<p>长度分布偏斜的典型场景是长短请求混排：一条长时长请求的端到端截止时间 $d_i$ 绝对值大，但它的剩余执行时间 $\\hat{t}_i^{\\text{rem}}$ 也大，紧迫度 $u_i$ 可能反而低于一条短时长但截止时间紧的请求。若调度器只看绝对截止时间，长请求会长期占据队头并撑大 batch，短请求被压在后面，帧间隔 SLO 先崩。正确的做法是按 $u_i$ 排序，让短请求优先并入下一批，长请求在显存有余量时搭车。这要求长度分布已知且画像准确——长度分布的方差越大，$\\hat{t}_i^{\\text{rem}}$ 的估算误差越容易让排序翻转。</p>\n<p>批大小的动态上限还需要按队列深度设闸。队列深度上升时，若继续放大 batch，单步时间线性增长，所有在批请求的帧间隔同时恶化；此时应收缩 batch 上限，用更多批次换更短的单步时间，把 SLO 违约从“全体”压缩到“尾部”。这个闸门的阈值依赖模型与硬件画像，跨 Blackwell SKU 未重新标定时，闸门会开在错误的位置。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-24\">二十四 · 并发形态：稳态与突增的分界</h3>\n<p>并发对这套机制的意义不在于峰值数字，而在于并发到达的形态。稳态并发下，采样队列与 VAE 队列深度稳定，调度器按紧迫度做常规批组合，降级阶梯不触发，系统运行在 SLO 满足率的高原区。突增并发下，队列深度在短时间内跃升，采样阶段的显存预算先被耗尽，新请求无法并入 batch，首帧时延开始爬升。此时降级阶梯（减步、降分辨率、跳帧）是唯一的泄压阀。</p>\n<p>降级触发过晚是连锁违约的起点。采样阶段已积压大量请求时，减步与降分辨率无法及时释放显存——已经在批的请求不会中途降级，只有新准入的请求能享受降级，而队列里排队的请求仍在按原配方等待。结果是采样阶段持续满载、VAE 阶段因 latent 供给不足而空转，两个阶段的资源配比彻底失衡。工程上必须把降级信号反馈给准入控制：当队列深度超过阈值时，准入控制直接拒绝或延迟接纳新请求，而不是让它们进入队列后再降级。拒绝比排队后违约更省 GPU 时间，因为违约请求不计入吞吐却消耗了采样算力。</p>\n<p>并发形态还影响阶段资源配比。采样与 VAE 可分配不同卡组或不同并行轴，配比按两阶段的稳态负载比值设定。突增时采样阶段先饱和，若配比固定，VAE 卡组会闲置；动态调整阶段资源配比需要跨卡组的调度权限，这在单节点多卡部署下可行，在跨节点时受 NVLink 域与通信开销约束。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-25\">二十五 · 负载不对时的三种失效</h3>\n<p>第一种失效是画像失准。SLO 估算依赖模型与硬件画像，跨模型或跨 Blackwell SKU 未重新标定时，$\\hat{t}_i^{\\text{rem}}$ 的系统性偏差会让紧迫度排序整体失真。若画像低估了长请求的剩余时间，长请求的 $u_i$ 被高估，它们挤占队头并撑大 batch，短请求的首帧 SLO 先违约；若画像高估，短请求被过度优先，长请求的端到端 SLO 在窗口末尾集中违约。两种方向的失准都表现为“高优请求被低优请求挤占”，但根因在标定而非排序逻辑。</p>\n<p>第二种失效是 latent 队列积压。采样阶段产出 latent 的速率超过 VAE 阶段消费速率时，latent 队列深度单调上升，显存被队列缓冲吃掉，采样阶段的可用显存预算收缩，batch 上限被动下降，采样吞吐随之下降——这是一个正反馈的恶化环。VAE 阶段成为瓶颈的诱因通常是微批并行度不足或 VAE 卡组配比偏低，而采样阶段的空转是结果而非原因。监控必须同时看两个队列的深度比值，只看 GPU 利用率会误判为“采样阶段不够快”。</p>\n<p>第三种失效是短请求下的固定成本倒挂。两阶段队列与 latent 搬运的调度开销在短请求上占比过高，吞吐反而低于静态批处理。此时解耦的收益被固定成本吞没，工程判断是：当配方中短请求（低分辨率、少步数、短时长）占比超过某个由画像标定确定的阈值时，应把这类请求路由到不拆阶段的快速路径，而不是让它们走完整的两阶段流水。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发条件</th><th>观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>画像失准</td><td>跨模型/SKU 未重标定</td><td>紧迫度排序与真实截止时间背离</td><td>首帧或端到端 SLO 集中违约</td></tr><tr><td>latent 积压</td><td>VAE 消费速率低于采样产出</td><td>两队列深度比值持续上升</td><td>显存被队列占用，采样 batch 上限下降</td></tr><tr><td>固定成本倒挂</td><td>短请求占比高</td><td>调度开销占单请求耗时比例上升</td><td>吞吐低于静态批处理</td></tr></tbody></table>\n\n<h3 id=\"alg-streaming-serving-slo-sec-26\">二十六 · 配方与部署配比的联合标定</h3>\n<p>负载配方不是独立于部署配方的输入，两者必须联合标定。硬件档位按峰值并发与单请求显存画像选择，通常单节点多卡；采样与 VAE 的卡组配比按配方中两阶段的稳态负载比值设定。量化可用 FP8/NVFP4 压缩采样激活与 VAE 输入，这会改变单请求显存画像与单步时间，进而改变画像标定的基准——量化上线后必须重标定，否则紧迫度排序的输入已经失真。KV 策略按请求隔离并在请求结束后立即回收，避免跨请求污染，这也意味着配方中并发数的上限受 KV 显存池大小约束，而非仅受采样激活约束。</p>\n<p>标定的产出是一组画像参数：各分辨率档的单帧采样时间、各步数档的单步时间、VAE 微批的单帧解码时间、以及对应的显存占用。调度器用这组参数计算 $\\hat{t}_i^{\\text{rem}}$ 与显存预算，准入控制用同一组参数判断新请求能否在 SLO 窗口内完成。配方变化（新增分辨率档、步数档调整、量化切换）都触发重标定，这是这套机制规模上限的来源：画像标定精度与队列内存决定它能服务多宽的配方，而不是 GPU 算力。</p>\n<p>最终落在工程判断上：负载配方的设计目标不是追求最宽的异构度，而是让画像标定的组合数、两阶段队列深度的匹配度、以及短请求固定成本的占比三者同时落在可控区间。配方越窄，标定越准，但批组合的腾挪空间越小；配方越宽，腾挪空间越大，但估算残差与固定成本倒挂的风险同步上升。调度器的动态 batch 上限与降级阶梯只是在这个区间内做局部调节，配方本身决定了区间的边界。</p>\n<h3 id=\"alg-streaming-serving-slo-sec-27\">二十七 · 硬件档位：按峰值并发与单请求显存画像定档</h3>\n<p>部署配方的第一刀切在硬件档位。流式视频生成服务的硬件选型不能看单卡峰值算力，而要看“在目标 SLO 下能同时容纳多少个请求的采样与 VAE 阶段”。单请求显存画像由分辨率、时长、步数三者共同决定：分辨率抬高时空 latent 的通道维度与注意力工作集同步膨胀，时长拉长时 KV 或 latent 序列长度线性增长，步数则直接乘以采样阶段的驻留时间。因此档位划分的正确做法是先固定一组代表性请求形态（例如低分辨率短时长、中分辨率中时长、高分辨率长时长三档），分别测出采样阶段的常驻显存与 VAE 阶段的峰值显存，再按“峰值并发 × 单请求画像 + 阶段队列缓冲”反推卡数与显存容量。</p>\n<p>Blackwell 的 SM100/SM103 在单节点内提供 NVLink 5 域，这决定了档位的基本粒度是“单节点多卡”而非跨节点拼凑：采样阶段的 tensor 并行与 VAE 阶段的微批并行都落在同一 NVLink 域内，跨阶段 latent 队列的搬运也不必过 PCIe 或网络。工程判断是：档位不应按“最大分辨率单请求能跑”来定，而应按“目标并发下 VAE 阶段不成为瓶颈”来定，因为 VAE 解码的显存峰值往往比采样阶段更陡——它要同时持有 latent、解码中间激活与输出帧缓冲。</p>\n<p>档位选择直接换算成代价：档位过低时，显存预算压缩 batch 上限，采样阶段连续批处理的插入机会变少，GPU 占用率下滑，帧间隔 SLO 首先告急；档位过高时，低负载下多卡空转，功耗与单位请求成本上升。可用事实给出的方向是“按峰值并发与单请求显存画像选择，通常单节点多卡”，这意味着档位表应以并发档位（而非模型档位）为主键，同一模型在不同并发目标下可能落在不同硬件档位。</p>\n<div class=\"formula\">$$\\text{GPU}_{\\text{need}}=\\left\\lceil\\frac{C_{\\text{peak}}\\cdot (M_{\\text{sample}}+M_{\\text{vae}})+M_{\\text{queue}}}{M_{\\text{card}}}\\right\\rceil$$</div>\n<p>其中 $C_{\\text{peak}}$ 为目标峰值并发，$M_{\\text{sample}}$、$M_{\\text{vae}}$ 为单请求两阶段显存画像，$M_{\\text{queue}}$ 为 latent 队列缓冲。这个式子只做容量下界估算，真正的约束是 VAE 阶段的峰值而非均值。举例：一个以中分辨率中时长为主的服务，若 VAE 阶段单请求峰值显存接近采样阶段的两倍，则档位必须为 VAE 留出独立卡组，否则采样 batch 会被 VAE 的显存峰值反向压缩。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-28\">二十八 · 并行拓扑：采样与 VAE 分卡组、分并行轴</h3>\n<p>拓扑设计的核心是把两个资源特征不同的阶段放到不同的并行轴上。采样阶段是 DiT 去噪迭代，计算密集、序列长、对 tensor 并行与序列并行敏感；VAE 阶段是逐帧或逐块的解码，访存密集、单块工作量小、对微批并行敏感。把两者塞进同一组卡、同一并行度，会让采样阶段的并行通信与 VAE 阶段的微批调度互相牵制。部署配方上应明确：采样卡组按模型并行轴切分（张量并行度由单层宽度与 NVLink 带宽决定），VAE 卡组按微批并行切分（并行度由单帧解码的显存与计算量决定），两组之间只通过 latent 队列通信。</p>\n<p>跨阶段解耦的代价是 latent 搬运。latent 张量本身不大，但搬运带来同步点：采样完成一个请求的最后一帧 latent 后要写入队列并通知 VAE 卡组，VAE 卡组要按帧或块微批组批后再解码。同步开销在短请求下占比显著——请求时长越短，latent 搬运与队列唤醒的固定成本越难摊薄。因此拓扑上应让 latent 队列驻留在 NVLink 域内的显存或主机锁页内存中，避免跨节点搬运；同时队列深度要设上限，防止采样阶段持续产出而 VAE 阶段消费不及导致积压。</p>\n<p>另一个拓扑判断是资源配比是否静态。可用事实给出的机制包含“动态调整 batch 上限与阶段资源配比”，但在物理拓扑上，卡组划分通常是静态的，动态调整发生在 batch 上限与降级阶梯上。若负载长期偏向某一阶段，静态卡组划分会造成另一侧空转，此时需要靠准入控制与降级把负载压回平衡点，而不是频繁重划卡组。举例：当 VAE 队列深度持续超过阈值而采样队列见底，说明 VAE 卡组不足，调度器应下调采样 batch 上限、收紧准入，而不是继续往采样阶段塞请求。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>并行轴</th><th>批处理方式</th><th>主要代价</th></tr></thead><tbody><tr><td>采样（DiT）</td><td>张量/序列并行，NVLink 域内</td><td>连续批处理，步间插入</td><td>并行通信、显存常驻</td></tr><tr><td>VAE 解码</td><td>微批并行，按帧/块</td><td>微批组批，流式返回</td><td>访存带宽、输出缓冲</td></tr><tr><td>跨阶段</td><td>latent 队列</td><td>解耦，深度受限</td><td>同步与搬运固定开销</td></tr></tbody></table>\n\n<h3 id=\"alg-streaming-serving-slo-sec-29\">二十九 · 量化方案：采样激活与 VAE 输入分别定精度</h3>\n<p>量化在部署配方里不是一刀切。采样阶段的 DiT 激活与权重可用 FP8 或 NVFP4 压缩，收益体现在显存占用与 MMA 吞吐上；VAE 阶段的输入是 latent，其数值动态范围与解码对精度的敏感度不同于采样激活，量化方案要单独定。可用事实明确“量化可用 FP8/NVFP4 压缩采样激活与 VAE 输入”，但没有给出具体精度分配比例，因此配方上应把量化档位作为可配置项，按请求形态分档：高分辨率长时长请求优先保采样精度以守住画面稳定性，低分辨率短请求可激进压缩以换吞吐。</p>\n<p>量化带来的系统代价是双向的。显存侧，激活压缩直接抬高单卡可容纳的 batch 上限，进而抬高连续批处理的插入频率与 GPU 占用率；带宽侧，低精度激活减少采样阶段层间搬运与 latent 写队列的字节数，缓解 NVLink 与显存带宽压力。但量化也引入数值风险：VAE 输入若量化过粗，解码后的帧间一致性可能退化，表现为帧间隔 SLO 达标但画质不达标——这类退化不在 SLO 公式里，却会在准入与降级策略中反向体现为请求被重试或降级。</p>\n<p>配方上的可复现做法是：把量化档位与请求形态绑定成一张表，采样阶段按分辨率与步数选 FP8 或 NVFP4，VAE 输入按输出帧率与块大小选精度；每次跨 Blackwell SKU 或换模型时重新标定这张表，因为画像失准会同时污染 SLO 估算与量化收益估算。举例：同一服务在 B200 与 GB200 NVL72 上，NVLink 域规模不同，采样并行度与 latent 搬运路径不同，量化档位表不能直接照搬，必须重标。</p>\n<div class=\"formula\">$$M_{\\text{act}}\\approx \\frac{S\\cdot H\\cdot b_{\\text{act}}}{8},\\quad \\text{batch}_{\\max}\\propto \\frac{M_{\\text{card}}-M_{\\text{static}}}{M_{\\text{act}}+M_{\\text{kv}}}$$</div>\n<p>其中 $b_{\\text{act}}$ 为激活位宽，$M_{\\text{static}}$ 为权重与常驻缓冲。位宽减半近似使可容纳 batch 翻倍，但真实上限受 VAE 峰值与队列缓冲挤压，配方上应留出安全余量而非按理论值顶格设 batch。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-30\">三十 · KV 与 latent 策略：按请求隔离、结束即回收</h3>\n<p>流式视频生成的自回归形态会引入 KV 或等价的历史缓存，部署配方必须明确其生命周期。可用事实给出的策略是“按请求隔离并在请求结束后立即回收，避免跨请求污染”。这条策略在工程上有两层含义：一是缓存不跨请求复用，杜绝不同请求的 latent 或 KV 混批导致的内容串扰；二是回收要即时，因为流式服务的请求完成时刻分散，延迟回收会让显存碎片化，压缩后续 batch 的上限。</p>\n<p>与 KV 策略并列的是 latent 队列的驻留策略。采样完成的 latent 进入 VAE 队列等待解码，这段驻留时间直接占用显存。队列深度上限就是 latent 驻留显存的上限，配方上应把队列深度与 VAE 卡组的消费速率绑定：消费速率由微批并行度与单帧解码时间决定，队列深度设为其若干倍即可，过深只会增加显存压力而不提升吞吐。短请求场景下，latent 驻留时间短、队列周转快，但调度与搬运的固定开销占比高，此时应缩小队列深度、提高 VAE 微批的启动频率。</p>\n<p>代价体现在显存与同步两侧：按请求隔离意味着缓存不能通过共享来摊薄，单请求显存画像因此偏高；即时回收意味着回收动作与调度动作耦合，回收不及时会形成碎片，回收过频会增加调度开销。举例：一批短请求同时完成采样，若回收滞后，VAE 卡组在组微批时找不到连续显存块，只能拆成更小的微批，单帧等待上升，帧间隔 SLO 首先被击穿。配方上应把回收动作挂在请求完成回调上，而不是等周期扫描。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-31\">三十一 · 调度参数：batch 上限、紧迫度阈值与降级阶梯</h3>\n<p>调度参数是部署配方里最需要标定的一组数。可用事实给出的紧迫度定义为 $u_i=(d_i-\\hat{t}_i^{\\text{rem}})/\\hat{t}_i^{\\text{rem}}$，调度器优先把 $u_i$ 大的请求并入下一批。配方上要定三个参数：紧迫度阈值（超过多少必须并入本批）、batch 上限（由显存预算与队列深度共同约束）、降级阶梯的触发点。这三个参数互相耦合：阈值过低会让低优请求挤占 batch，阈值过高会让高优请求等待；batch 上限过高会让单批延迟拉长，上限过低会让 GPU 占用不足。</p>\n<p>降级阶梯按“减步、降分辨率、跳帧”排序，触发依据是 SLO 违约风险而非事后违约。可用事实指出失败模式包括“降级触发过晚造成连锁违约”，因此配方上应把触发点设在紧迫度分布的尾部：当队列中高紧迫度请求占比超过阈值，或 VAE 队列深度持续超限，就提前降级并反馈准入控制，而不是等首帧时延已经越界。降级阶梯要粗到可执行、细到可回退，每一级对应明确的资源释放量（减步释放采样时间、降分辨率释放显存与计算、跳帧释放 VAE 工作量）。</p>\n<p>调度参数的代价是估算误差。$\\hat{t}_i^{\\text{rem}}$ 依赖模型与硬件画像，跨模型或跨 Blackwell SKU 未重标定时，紧迫度排序会失真，高优请求被低优挤占。配方上应把画像标定作为部署前置步骤，并在运行期用实际完成时间回写画像，形成闭环。举例：新模型上线未标定，采样阶段剩余时间被低估，紧迫度普遍偏高，调度器把所有请求都当高优并入 batch，batch 上限被瞬间打满，VAE 队列积压，帧间隔 SLO 连锁违约——这正是画像失准的典型路径。</p>\n<div class=\"formula\">$$\\text{batch}_{\\max}=\\min\\left(\\text{batch}_{\\text{mem}},\\ \\text{batch}_{\\text{slo}}\\right),\\quad \\text{batch}_{\\text{slo}}=\\arg\\max_b\\{b:\\ \\hat{T}_{\\text{batch}}(b)\\le D_{\\text{frame}}\\}$$</div>\n<p>即 batch 上限取显存约束与帧间隔约束的较小者。配方上应把 $\\text{batch}_{\\text{slo}}$ 按请求形态分档预计算，运行期只做查表与微调，避免每批都解一次优化问题。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-32\">三十二 · 可复现的配置思路：先画像、再分档、后闭环</h3>\n<p>把上述选择串成可复现流程，顺序是画像、分档、闭环三步。第一步画像：固定三档代表性请求形态，测出采样阶段常驻显存与单步时间、VAE 阶段峰值显存与单帧解码时间、latent 搬运延迟，形成模型与硬件画像表。第二步分档：按峰值并发目标选硬件档位，按阶段资源特征划采样与 VAE 卡组，按请求形态绑定量化档位与 KV/latent 回收策略，按画像预计算 batch 上限与紧迫度阈值。第三步闭环：运行期监控队列深度与 GPU 利用率，用实际完成时间回写画像，按违约风险触发降级并反馈准入控制。</p>\n<p>这套流程的可复现性来自参数与画像的显式绑定，而非调参直觉。配方上应把每个参数标注其来源（画像测得、预计算、运行期回写），跨 SKU 或换模型时只重跑画像与预计算两步，卡组划分与降级阶梯结构保持不变。代价是标定工作量：每换一次模型或硬件组合都要重测画像，短请求场景下还要额外测调度与搬运的固定开销，否则两阶段队列的收益会被固定成本吃掉。</p>\n<p>工程判断落在准入控制这一环：部署配方的终点不是把 batch 打满，而是在 SLO 守门的前提下让两阶段流水保持节拍。当画像显示 VAE 阶段是瓶颈，配方应主动收紧准入而非扩大采样 batch；当画像显示短请求占比高、固定开销压过收益，配方应退回更粗的批处理粒度甚至合并阶段。可用事实给出的适用边界正是“极短请求或极低并发下两阶段队列与 latent 搬运的固定开销可能超过收益”，因此配方必须包含一条回退路径，把“解耦”作为可关闭的开关，而不是默认恒开的结构。</p>\n<p>最后一条具体机制：把降级反馈写进准入控制的令牌桶。每个降级事件按释放的资源量折算成令牌回收，准入侧据此下调放行速率；当画像回写显示实际完成时间优于估算，令牌再逐步释放。这样降级不是一次性动作，而是与画像闭环耦合的持续调节，避免“降级触发过晚”与“降级后无法回退”两种失败模式在同一服务上交替出现。</p>\n<h3 id=\"alg-streaming-serving-slo-sec-33\">三十三 · 显存账本：谁在占用，谁在等</h3>\n<p>把两阶段队列拆开之后，显存不再是一块被批大小统一支配的连续预算，而是分成三本账：采样侧的活动批显存、latent 队列的暂存显存、VAE 侧的微批工作显存。采样侧的占用由 batch 内各请求的 latent 序列长度、注意力工作区与权重共同决定，且随连续批处理在步间插入新请求而动态增长；latent 队列的占用是已完成采样但尚未解码的请求留下的中间结果，它与采样吞吐成正比、与 VAE 解码速率成反比；VAE 侧则按帧或块切微批，单批工作显存小但并发微批数受显存与带宽双重约束。三本账的耦合点在于：latent 队列积压时，采样侧仍可继续吃显存扩批，直到队列暂存把总预算吃满，此时调度器要么停止接纳新请求，要么压缩采样批，两种选择都会立刻反映到 SLO 上。</p>\n<p>一个可操作的判据是把显存预算写成约束式：设采样批显存为 $M_s(b_s)$、latent 队列占用为 $M_q(n_q)$、VAE 微批显存为 $M_v(b_v)$，则可行域是 $M_s(b_s)+M_q(n_q)+M_v(b_v)\\le M_{\\text{card}}$。调度器每次调整 batch 上限，本质上是在这个不等式上做一次投影。代价很直接：$M_q$ 一旦逼近上限，$b_s$ 被迫收缩，采样吞吐下降，而 $b_v$ 又受 VAE 单帧延迟约束不能无限扩大，于是系统进入“队列越积、采样越慢、队列更积”的正反馈。工程上必须给 $M_q$ 设硬上限并触发背压，而不是让它自由生长。</p>\n<p>具体例子：一批混合 720p 与 1080p 的请求同时到达，1080p 请求的 latent 序列长度显著更长，若调度器只按请求数而非按显存估算组批，采样批里塞进两个 1080p 请求就会把 $M_s$ 推高，挤掉原本留给 $M_q$ 的余量，VAE 侧微批被迫串行化，帧间隔 SLO 首先在这类请求上破裂。显存是第一个崩的地方，但它崩的信号出现在队列深度而不是利用率上。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-34\">三十四 · 带宽与通信：latent 搬运的隐性税</h3>\n<p>阶段解耦的代价之一是 latent 必须在采样卡组与 VAE 卡组之间搬运。若两阶段分置在不同卡上，这笔搬运走 NVLink 5 或节点内互联；若跨节点，则走 NCCL 集合通信或 NIXL 点对点传输。搬运量看似不大——latent 相比像素帧是压缩表示——但它是每请求每帧都要发生的，且与解码节奏耦合：VAE 按帧微批解码，意味着 latent 需要按帧粒度持续供给，而不是一次性大块传输。这把通信从“一次性带宽事件”变成“持续性带宽占用”，与采样阶段的计算带宽需求叠加在同一张卡的内存系统上。</p>\n<p>量化这笔税的方式是看单位时间搬运字节与有效解码帧率的比值。设单帧 latent 字节数为 $B_l$、目标帧率为 $f$、并发解码请求数为 $n_v$，则跨阶段带宽需求约为 $n_v\\cdot B_l\\cdot f$。当 $n_v$ 随并发上升，这条带宽曲线会与采样侧的权重读取、激活读写争抢 HBM 带宽。代价表现为：VAE 微批的解码时间不再由算力决定，而由 latent 到达的抖动决定，帧间隔的尾延迟被通信抖动放大。</p>\n<p>具体例子：单节点多卡部署下，采样与 VAE 分卡，latent 经 NVLink 传输，单请求时延几乎无感；并发升到数十路后，VAE 侧多个微批同时等待各自的 latent 块，NVLink 上的小消息传输效率下降，解码微批出现空等，帧间隔的 P99 明显劣于 P50。此时把 VAE 微批的块尺寸调大能摊薄单次传输开销，但又会拉长单帧等待，形成块尺寸与尾延迟之间的直接权衡。通信不是第二个崩的地方，但它是最先让尾延迟脱离均值的环节。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-35\">三十五 · 功耗与时钟：持续高占用的降频陷阱</h3>\n<p>流式服务与离线批推理的功耗形态不同：离线批允许在批间隙让 GPU 回落，而流式服务要求采样阶段持续高占用以维持帧间隔，VAE 阶段又要频繁启停微批。持续高占用把 GPU 推到功耗上限附近，SM 时钟在功耗墙下被压，采样每步的实际耗时高于画像中标定的值。这一点直接破坏 SLO 估算：$\\hat{t}_i^{\\text{rem}}$ 若按峰值时钟标定，实际剩余时间被低估，紧迫度 $u_i$ 排序失真，高优请求可能被排在后面。</p>\n<p>机制上，调度器需要把功耗状态纳入画像，而不是把画像当成静态常量。可行做法是在监控环节同时采集队列深度、GPU 利用率与时钟/功耗读数，当检测到持续降频时，按比例放大剩余时间估计，并相应收紧 batch 上限——因为更大的批在降频下边际收益递减，反而拉长单步时间。代价是吞吐上限被功耗墙封顶：在 NVL72 这类高密度机柜里，整柜功耗预算会反过来约束单卡可用的持续功率，峰值并发下的帧率不是算力上限而是功耗上限。</p>\n<p>具体例子：多路 1080p 长视频请求同时流式输出，采样阶段长时间满载，时钟回落，单步时间拉长，帧间隔开始在部分请求上超限；调度器若仍按标定画像组批，会继续扩大采样批试图提吞吐，结果单步更慢、尾延迟更差。正确动作是缩小采样批、把释放出的功耗预算让给 VAE 微批，使解码节奏恢复。功耗是第三个崩的地方，且它崩的方式是让前两个环节的估算全部失准。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-36\">三十六 · 尾延迟：SLO 守门在长尾上的失效</h3>\n<p>吞吐公式 $\\text{throughput}=\\sum_r \\mathbb{1}[\\text{SLO}_r]/T_{\\text{window}}$ 把每个请求的三项约束压成一个布尔量，但尾延迟的问题在于：均值意义上的 SLO 满足率好看，长尾请求却在帧间隔上反复擦线。流式视频的帧间隔约束是逐帧的，$\\max_f(T_{f+1}-T_f)\\le D_{\\text{frame}}$，任何一帧的调度抖动都会让整个请求判负。两阶段队列的解耦在均值上减少了阶段间等待，但在尾部引入了新的抖动源：latent 队列的排队时间、VAE 微批的组批等待、跨阶段搬运的抖动，三者叠加在单帧上。</p>\n<p>调度侧的应对是把紧迫度从请求级下沉到帧级。请求级 $u_i$ 决定谁进下一批，帧级则需要判断某请求的下一帧是否已接近 $D_{\\text{frame}}$ 边界，若是则优先为其 latent 分配 VAE 微批槽位，甚至临时拆出单帧独占微批以压抖动。代价是这种抢占会打乱 VAE 微批的并行度，降低解码侧的整体吞吐，等于用吞吐换尾延迟。工程判断是：当并发超过某阈值、尾延迟成为主要违约来源时，应把 VAE 侧从“微批并行”切换为“按紧迫度分槽”，牺牲部分解码吞吐守住帧间隔。</p>\n<p>具体例子：一批短请求与少量长请求混跑，短请求因调度固定开销占比高而频繁擦线，长请求则在帧间隔上偶发超限；若调度器只按请求级紧迫度排序，短请求被反复插入采样批，长请求的 latent 在队列里等待，其帧间隔在等待期被拉长。把帧级紧迫度引入 VAE 分槽后，长请求的帧间隔尾部收敛，但短请求的吞吐下降，这正是尾延迟与吞吐的直接兑换点。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-37\">三十七 · 规模上去以后哪里先崩：崩序与工程判断</h3>\n<p>把四本账按规模排序，崩的顺序并不与直觉一致。显存最先给出信号，因为 $M_q$ 的增长是单调的且没有自愈机制；但显存崩溃之前，尾延迟已经在通信抖动与功耗降频的共同作用下脱离均值，只是监控若只看均值利用率就看不见。真正的连锁违约发生在画像失准之后：功耗降频让 $\\hat{t}_i^{\\text{rem}}$ 偏小，紧迫度排序失真，高优请求被挤，降级阶梯触发过晚，采样侧已积压大量请求，减步与降分辨率无法及时释放显存，违约沿队列扩散。这条链条的起点不是显存不够，而是估算与监控的粒度不够细。</p>\n<p>工程判断可以落成三条硬规则。其一，latent 队列设硬上限并触发背压，把显存崩溃挡在准入侧而不是批调度侧。其二，画像按 Blackwell SKU 分别标定并周期性用实测时钟与功耗读数校正，跨 SKU 不共用画像。其三，降级阶梯要前置：在队列深度越过阈值时就启动减步或降分辨率，而不是等到 SLO 已违约才降级，因为降级本身需要时间释放资源，滞后触发等于放弃守门。三条规则共同把“规模上去先崩在哪”从显存单点转移到可控的准入与画像环节。</p>\n<p>具体例子：峰值并发翻倍时，若只扩采样卡组而不扩 VAE 卡组，latent 队列迅速吃满暂存，采样侧被迫缩批，吞吐不升反降；此时按第一条规则背压准入、按第三条规则提前降级，系统在较低并发下维持 SLO 满足率，而不是在更高并发下全线违约。规模上限由画像标定精度与队列内存共同决定，这两者都不是靠加卡能解决的。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-38\">三十八 · 吞吐的边际收益与调度开销占比</h3>\n<p>两阶段队列与 latent 搬运的固定开销在短请求下占比过高，这是吞吐曲线的拐点来源。设单请求调度与搬运固定开销为 $c_0$、有效计算时间为 $t_c$，则调度开销占比为 $c_0/(c_0+t_c)$；短请求的 $t_c$ 小，占比迅速上升，扩批带来的吞吐增益被固定开销吃掉。工程上的判据是：当请求平均时长低于某阈值时，两阶段解耦的收益可能为负，此时应退回更粗粒度的批处理或合并阶段，而不是继续加调度层次。</p>\n<p>机制上，调度器可以按请求时长画像做分流：长请求走两阶段解耦路径，短请求走合并路径以减少队列与搬运次数。代价是两条路径并存增加实现复杂度与画像标定负担，但换来的是吞吐曲线在短请求区间不塌陷。这一判断与适用边界一致——收益随请求异构度与负载波动增大，极短请求或极低并发下固定开销可能超过收益。</p>\n<p>具体例子：一批步数很少、时长很短的请求涌入，两阶段队列的入队、latent 落盘/搬运、VAE 微批组批三次固定开销叠加，单请求端到端时间反而长于静态批处理；按分流规则把这些请求并入合并路径后，固定开销次数减少，首帧时延 SLO 恢复。吞吐的边际收益不是无限的，拐点由固定开销与有效计算的比值决定，而这个比值只能靠画像与实测来定位。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-39\">三十九 · 规模拐点：先崩在队列内存与画像失准，而非算力</h3>\n<p>两阶段解耦把 GPU 空转换成了队列积压，代价的形态随之改变。采样队列按显存预算组批，VAE 队列按帧/块微批，两队列之间靠 latent 队列传递，于是系统里同时存在三份显存占用：采样激活、排队中的 latent、VAE 解码工作区。并发上升时，latent 队列是唯一没有天然上限的缓冲——采样侧连续批处理只要还能塞进 batch 就继续收请求，而 VAE 侧微批并行受单帧等待约束不能无限加深，两侧吞吐一旦失配，积压全部堆在 latent 队列上。此时采样阶段仍显示高利用率，VAE 阶段成为瓶颈而采样侧实际在为空转生产，这是该方案最先崩的位置，且监控上表现为“GPU 利用率健康、SLO 违约上升”的错位信号。</p>\n<p>紧迫度排序的可靠性直接决定规模上限。调度器用 $u_i=(d_i-\\hat{t}_i^{\\text{rem}})/\\hat{t}_i^{\\text{rem}}$ 排序，而 $\\hat{t}_i^{\\text{rem}}$ 来自模型与硬件画像；跨 Blackwell SKU（B200 与 B300、GB200 与 GB300 NVL72 的卡组配比不同）或换模型未重新标定时，剩余时间估计的系统性偏差会让 $u_i$ 的序关系整体平移，高优请求被低优请求挤占，且这种失真在队列深时被放大——排序错误的代价不是单请求违约，而是违约沿队列连锁扩散。规模上去后，画像标定精度而非 FLOPS 才是硬约束。</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{ok}}\\iff T_{\\text{first}}\\le D_{\\text{first}}\\ \\wedge\\ \\max_f(T_{f+1}-T_f)\\le D_{\\text{frame}},\\quad \\text{throughput}=\\frac{\\sum_r \\mathbb{1}[\\text{SLO}_r]}{T_{\\text{window}}}$$</div>\n<p>上式说明吞吐的分母是时间窗、分子是守门计数，因此降级阶梯的触发时机比降级幅度更关键：减步、降分辨率、跳帧若在采样已积压后才触发，释放的显存赶不上新请求涌入，分子不增而分母被拖长。工程判断是把触发点前移到队列深度与 $u_i$ 分布的联合阈值上，并让准入控制消费同一信号；同时给 latent 队列设硬上限，宁可拒绝也不让其成为隐式无限缓冲。极短请求或极低并发下，两阶段队列与 latent 搬运的固定开销超过收益，此时应回退到静态批处理路径——这是该方案的明确失效条件，而非需要优化的缺陷。</p>\n<h3 id=\"alg-streaming-serving-slo-sec-40\">四十 · 画像失准：紧迫度排序的静默失真</h3>\n<p>失败模式里最隐蔽的一类是 SLO 估算偏差。调度器把请求并入哪一批，靠的是紧迫度 $u_i=(d_i-\\hat{t}_i^{\\text{rem}})/\\hat{t}_i^{\\text{rem}}$，而 $\\hat{t}_i^{\\text{rem}}$ 完全来自模型与硬件画像。画像失准不会报错、不会掉卡，只会让排序悄悄错位：高优请求被估成“还早”，低优请求被估成“很急”，于是前者在采样队列里多等了几轮连续批处理，首帧 SLO 直接违约，而监控面板上 GPU 利用率依旧漂亮。</p>\n<p>偏差来源有三类，必须分开诊断。其一是模型侧：换模型或换量化方案（FP8 切 NVFP4）后，采样步的实际耗时分布变了，但画像表还是旧的，$\\hat{t}_i^{\\text{rem}}$ 系统性偏乐观。其二是硬件侧：跨 Blackwell SKU 迁移，SM 数量、TMEM 容量、显存带宽都不同，同一 batch 上限在新卡上对应的实际占用时间不同。其三是请求侧：分辨率、时长、步数的组合落在画像采样点之外，估算靠插值，误差随组合异构度放大。</p>\n<p>诊断手段是把估算值与实测值做成逐请求的残差序列，而不是只看聚合指标。工程上给每个请求记一对 $(\\hat{t}_i^{\\text{rem}}, t_i^{\\text{actual}})$，按分辨率桶、步数桶、SKU 分桶统计残差的中位数与尾部。残差中位数持续偏负（实际比估算慢）就说明画像整体过时，需要重标定；残差尾部发散说明画像采样点覆盖不足，需要补点。代价上，逐请求残差记录本身是低开销的（一条结构化日志），但重标定是离线动作，会占用标定卡时，跨 SKU 标定更是必须排进发布流程的固定成本。判断准则：残差中位数偏移超过一个采样步的耗时量级，就应视为画像失效，而不是靠调 batch 上限去掩盖。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-41\">四十一 · OOM 与批抖动：显存预算的两种崩法</h3>\n<p>OOM 在流式视频服务里通常不是单请求太大，而是批组合瞬间越界。采样 batch 由显存预算与紧迫度共同决定，而预算里最容易被低估的是 latent 队列——采样完成的 latent 在等 VAE 解码时仍占显存，队列一积压，采样阶段可用的显存就被悄悄吃掉。此时调度器按旧预算继续组批，下一次组批就撞上 OOM。诊断要点是把显存占用拆成三段分别监控：采样激活、latent 队列驻留、VAE 解码工作区。三段中任何一段的增速与队列深度不匹配，就是 OOM 的前兆信号，而不是等 OOM 发生后再看总占用。</p>\n<p>批抖动是另一种崩法：batch 上限被监控回路频繁调整，导致每批的实际组成在相邻批次间大幅跳变。连续批处理在步间插入新请求，若上限忽高忽低，插入时机与批内请求的剩余步数错配，GPU 占用率呈锯齿状，帧间隔 SLO 在锯齿谷底违约。抖动根因往往是监控回路用了过短的时间窗——队列深度的瞬时抖动被当成趋势，触发上限调整，调整又反过来制造新的抖动。</p>\n<div class=\"formula\">$$\\text{batch}^{\\max}_{t+1}=\\text{clamp}\\Big(\\text{batch}^{\\max}_{t}+\\kappa\\,(\\rho_{\\text{target}}-\\rho_t),\\ B_{\\min},\\ B_{\\max}\\Big)$$</div>\n<p>式中 $\\rho_t$ 是平滑后的 GPU 占用率，$\\kappa$ 是步长。关键是 $\\rho_t$ 必须用足够长的时间窗平滑，且 $B_{\\min}$ 不能设得过低——短请求下调度开销占比高，批太小会让固定开销吃掉收益。代价上，抖动本身不增加显存，但会让有效吞吐下降，因为每批的启动与收尾开销被重复支付。具体例子：混合分辨率请求流里，高分辨率请求集中到达时占用率骤升，若回路立即压低上限，随后到达的一批短请求就被迫串行，帧间隔尖刺出现。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-42\">四十二 · 路由不均与 latent 队列积压</h3>\n<p>采样与 VAE 分配在不同卡组或不同并行轴后，路由不均表现为某一侧队列持续加深而另一侧空转。典型形态是 VAE 阶段成为瓶颈：latent 队列积压，采样阶段因为下游不消化而被迫压低 batch，GPU 空转，而 VAE 卡组满负荷。这不是单点故障，是资源配比与请求形态不匹配——VAE 微批并行对短请求友好，但对长时长、高分辨率请求，单帧解码工作量大，微批并行度不够就会堵。</p>\n<p>诊断路由不均不能只看两侧的平均利用率，要看队列深度的比值与其导数。采样队列深度与 VAE 队列深度的比值持续偏离设计配比，且 VAE 侧导数持续为正，就是配比失衡的确认信号。此时正确的动作是调整阶段资源配比（把卡组或并行轴重新划分），而不是在采样侧降级——降级减步只会让采样更快地产出 latent，进一步加剧 VAE 积压，形成“越降越堵”的反向连锁。</p>\n<p>代价上，latent 搬运本身增加显存与同步开销，跨卡组搬运还要走 NVLink 或主机内存，短请求下这笔固定成本占比过高，吞吐可能低于静态批处理。工程判断：当请求的平均时长低于某个阈值（由搬运开销与单请求计算量之比决定），两阶段解耦的收益被固定成本抵消，应退回单阶段批处理或合并卡组。这个阈值必须按 SKU 实测标定，不能跨卡沿用。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-43\">四十三 · 尾延迟尖刺：降级触发时机的诊断</h3>\n<p>尾延迟尖刺的根因常是降级触发过晚。降级阶梯（减步、降分辨率、跳帧）设计得再细，若触发条件是“SLO 已违约”而非“违约风险高”，就已经晚了：采样阶段积压了大量请求，减步释放的显存不足以让队列回落，违约沿队列连锁扩散。诊断的关键是把触发条件从结果指标改成风险指标——用紧迫度分布的上分位数与队列深度的组合做前兆判据，而不是等 $T_{\\text{first}}$ 越线。</p>\n<p>另一个尖刺来源是降级阶梯过粗。只减步不降分辨率，对显存压力大的请求释放有限；只降分辨率不减步，对时间压力大的请求无效。阶梯必须按请求的资源瓶颈类型分流：显存瓶颈走降分辨率与跳帧，时间瓶颈走减步。分流错了，降级动作打在非瓶颈上，尖刺照旧。</p>\n<p>监控上，尾延迟要用分位数而非均值，且分位数要按请求形态分桶——混合分辨率流里，均值会被大量短请求稀释，长请求的尖刺被淹没。代价上，降级本身降低单请求质量，频繁误触发会浪费算力在“降了又恢复”的往复上；触发过晚则直接违约。判断准则：降级触发后若队列深度在若干个调度周期内未回落，说明阶梯选错或触发太晚，应立即升级到更激进的阶梯并同时收紧准入，而不是继续微调。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-44\">四十四 · 监控面与回滚路径</h3>\n<p>监控面要覆盖四层，缺一层就会在故障时失去定位能力。第一层是逐请求 SLO 判定：$T_{\\text{first}}$、$\\max_f(T_{f+1}-T_f)$、端到端时长三项各自打点，并按分辨率/步数/SKU 分桶。第二层是队列与显存三段：采样队列深度、VAE 队列深度、latent 驻留量、采样激活、VAE 工作区。第三层是画像残差：估算与实测的逐请求偏差。第四层是降级与准入事件：触发次数、阶梯类型、准入拒绝率。</p>\n<p>回滚路径要按故障类型分层，而不是一刀切回退到上一版本。画像失准的回滚是切回上一版标定表并冻结调度参数调整；OOM 与批抖动的回滚是收紧 batch 上限到保守值并拉长监控时间窗；路由不均的回滚是恢复上一版阶段资源配比；尾延迟尖刺的回滚是提高降级触发灵敏度并临时收紧准入。每一层回滚都应记录触发它的具体监控信号，否则下次同类故障仍然要靠人猜。</p>\n<p>吞吐口径要与 SLO 判定绑定：$\\text{throughput}=\\sum_r \\mathbb{1}[\\text{SLO}_r]/T_{\\text{window}}$，分母是观测窗而非请求总时长，分子只计满足全部三项 SLO 的请求。这个口径让“吞吐高但违约多”无法伪装成好结果，也让回滚决策有统一标尺。代价上，逐请求三项打点与分桶统计带来可观测性开销，高并发下日志量可观，需要采样或聚合后再落盘。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-45\">四十五 · 诊断顺序与工程判据</h3>\n<p>故障发生时按固定顺序排查，能避免在错误层反复调参。先看画像残差：残差偏移则一切排序与估算都不可信，先重标定再谈其他。再看显存三段：哪一段增速异常，就定位到对应阶段。再看队列深度比值：比值失衡说明配比问题，不是批大小问题。最后看降级事件时序：触发是否早于违约、阶梯是否打在瓶颈上。这个顺序的依据是因果链——画像错会伪造出 OOM 与尖刺的表象，先修上游才能看清下游。</p>\n<p>工程判据可以压成三条硬规则。其一，任何调度参数调整都必须有对应的监控信号与回滚点，没有回滚点的调整不进生产。其二，跨模型或跨 Blackwell SKU 必须重标定画像与搬运开销阈值，标定未完成前按保守 batch 上限运行并收紧准入。其三，降级触发必须用风险前兆而非违约结果，且阶梯按瓶颈类型分流。三条规则覆盖了画像失准、OOM、批抖动、路由不均、尾延迟尖刺五类失败模式的主要入口，剩下的边角靠逐请求残差与队列导数兜底。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-46\">四十六 · 画像漂移与队列反压：这套调度的失效边界</h3>\n<p>这套阶段解耦调度最脆弱的环节不是批组合算法本身，而是 SLO 紧迫度公式所依赖的剩余时间估计。调度器用 $u_i=(d_i-\\hat{t}_i^{\\text{rem}})/\\hat{t}_i^{\\text{rem}}$ 排序，其中 $\\hat{t}_i^{\\text{rem}}$ 来自模型与硬件画像；一旦跨模型或跨 Blackwell SKU 未重新标定，$\\hat{t}_i^{\\text{rem}}$ 的系统性偏差会让排序整体失真——高估慢请求的剩余时间会把紧迫请求压后，低估则让低优请求抢占采样 batch 的显存预算。诊断上应把画像预测值与实测阶段耗时按请求形态分桶对比，偏差超过阈值即冻结当前排序策略、退回按截止时间单调排序的保守模式，而不是继续用失真的 $u_i$ 做准入。</p>\n<p>第二类失效是降级阶梯与队列深度的耦合失配。降级（减步、降分辨率、跳帧）只有在采样队列尚未积压时才能释放显存；若触发阈值设在队列深度已经很高之后，减步带来的显存回收赶不上新请求的准入速度，违约会沿队列连锁扩散。工程上应把降级触发点绑定到 latent 队列的积压速率而非绝对深度，并让降级信号直接反压准入控制——拒收新请求比让已入队请求集体违约代价更低。第三类是 latent 队列积压使 VAE 阶段成为瓶颈而采样卡空转，此时 GPU 利用率监控会呈现两阶段反向背离，是识别阶段资源配比失衡的直接信号。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>画像失准</td><td>预测/实测阶段耗时偏差分桶上升</td><td>退回截止时间单调排序</td></tr><tr><td>降级过晚</td><td>队列深度增速超过显存回收速率</td><td>降级前置并收紧准入</td></tr><tr><td>阶段失衡</td><td>采样与 VAE 利用率反向背离</td><td>重配卡组与微批上限</td></tr></tbody></table>\n<p>系统代价必须计入回滚路径本身：两阶段队列与 latent 搬运的固定开销在短请求、低并发下可能超过收益，此时正确判断是回退到静态批处理而非继续调参。监控应以 $\\text{SLO}_{\\text{ok}}\\iff T_{\\text{first}}\\le D_{\\text{first}}\\wedge\\max_f(T_{f+1}-T_f)\\le D_{\\text{frame}}$ 逐请求判定，用 $\\text{throughput}=\\sum_r\\mathbb{1}[\\text{SLO}_r]/T_{\\text{window}}$ 作为回滚决策的统一口径——尾延迟尖刺与路由不均都应先折算成该窗口内违约请求数，再决定是切换并行拓扑还是整体回退。</p>\n<h3 id=\"alg-streaming-serving-slo-sec-47\">四十七 · 对照轴：先分清\"改算法\"与\"改调度\"</h3>\n<p>把本模块的十来个条目摆在一起，最容易犯的错是按\"谁更先进\"排序。正确的做法是先问一句：这个算法动的是单请求内部的执行路径，还是多请求之间的资源分配？本条目（阶段解耦 + 动态批 + SLO 守门）属于后者——它不改变 DiT 的一次前向，也不改变 VAE 的一次卷积，它改变的是\"哪个请求在什么时候占用哪块 SM\"。因此它天然与所有\"改单请求路径\"的算法正交，可以叠加，而不是互斥。判断一个候选算法是否与本条目同层，看它是否需要一个跨请求的全局视图：NVFP4 视频 DiT 量化、FP8 时空注意力内核、VAE 分块重叠解码、少步蒸馏采样、动态稀疏时空注意力、精度分配稀疏注意力，都只需要单请求内部的张量与核函数信息，属\"内核层\"；轨迹感知缓存复用、自回归视频 2bit KV 量化、视频自回归投机解码，需要请求内的历史状态但不需要跨请求比较，属\"请求内层\"；预填解码分离服务与长视频流式分块重叠，前者跨请求、后者请求内，是两个不同层的邻居。本条目与预填解码分离最像，但对照点在于：预填/解码分离切的是 Transformer 的两个计算阶段（prefill 是计算密集、decode 是带宽密集），本条目切的是 DiT 采样与 VAE 解码两个语义阶段，后者的资源特征差异不在算术强度，而在批处理粒度与输出节奏——采样要大步连续批处理保占用，VAE 要微批并行保单帧时延。</p>\n<p>由此得到第一条选型原则：内核层算法决定单请求的\"单位成本\"，调度层算法决定这些单位成本在时间轴上如何拼成 SLO。若单请求成本已经无法满足 $D_{\\text{frame}}$，任何调度都救不回来；若单请求成本远低于 SLO 但吞吐上不去，则问题一定在调度层。工程上先用画像测出单请求在目标 SKU 上的 $T_{\\text{first}}$ 与帧间隔下界，再决定往哪一层投入。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-48\">四十八 · 决策表：按负载形态选主算法</h3>\n<p>下表把同族条目按\"主导瓶颈\"归类，给出适用条件与不适用条件。表中\"叠加\"列指能否与本条目同时启用，以及叠加时的注意点。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>算法</th><th>作用层</th><th>主导瓶颈</th><th>适用条件</th><th>与本条目叠加</th></tr>\n</thead>\n<tbody>\n<tr><td>NVFP4/FP8 量化（DiT、VAE 输入）</td><td>内核层</td><td>显存容量与 HBM 带宽</td><td>显存吃紧、批大小被显存卡住</td><td>可叠加；量化后单请求显存画像变化，须重标定调度器的显存预算表</td></tr>\n<tr><td>FP8 时空注意力内核</td><td>内核层</td><td>注意力算力</td><td>高分辨率、长时空序列</td><td>可叠加；缩短采样步耗时，直接抬高采样队列的批上限</td></tr>\n<tr><td>少步蒸馏采样</td><td>内核层（步数）</td><td>采样总时长</td><td>$T_{\\text{first}}$ 或端到端时长紧</td><td>可叠加；步数下降使降级阶梯中的\"减步\"档位失效，需重设阶梯</td></tr>\n<tr><td>VAE 分块重叠解码 / 长视频分块重叠</td><td>请求内层</td><td>VAE 显存峰值与单帧时延</td><td>高分辨率、长时长</td><td>可叠加；分块后 VAE 微批的粒度变小，微批并行度可提高</td></tr>\n<tr><td>轨迹感知缓存复用</td><td>请求内层</td><td>重复步的计算量</td><td>相邻帧/步高度相似</td><td>可叠加；缓存命中使剩余时间估计 $\\hat{t}^{\\text{rem}}$ 非线性，画像须按命中率分档</td></tr>\n<tr><td>2bit KV 量化 / 投机解码（自回归视频）</td><td>请求内层</td><td>自回归解码带宽与串行步数</td><td>自回归式视频生成</td><td>可叠加；投机解码的接受率波动会放大帧间隔方差，调度需按方差而非均值排紧迫度</td></tr>\n<tr><td>动态稀疏 / 精度分配稀疏注意力</td><td>内核层</td><td>注意力算力与显存</td><td>稀疏性可预测</td><td>可叠加；稀疏度随内容变化，画像须给出耗时上界而非均值</td></tr>\n<tr><td>预填解码分离服务</td><td>调度层（跨请求）</td><td>两阶段算术强度失配</td><td>LLM 式长短混合请求</td><td>同层，择一为主；视频场景中 VAE 阶段的资源特征更接近 decode，可与本条目共用卡组划分思路</td></tr>\n<tr><td>本条目：阶段解耦 + 动态批 + 降级</td><td>调度层（跨请求）</td><td>阶段间空转与 SLO 违约</td><td>多请求并发、请求异构度高、负载有波动</td><td>—</td></tr>\n</tbody>\n</table>\n<p>读表的关键是\"主导瓶颈\"一列：一列里只能有一个主算法。若显存是硬约束，先上量化再谈调度；若显存充裕而 GPU 在阶段切换时利用率塌陷，则是本条目。表里\"叠加\"列的第二句往往比第一句更重要——上游算法改变了画像，而本条目全部决策都建立在画像之上，不重标定就等于让调度器用旧地图导航。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-49\">四十九 · 判据公式：什么条件下解耦才划算</h3>\n<p>解耦不是免费的。设采样阶段单请求平均占用时间为 $t_s$、VAE 阶段为 $t_v$，两阶段之间的 latent 搬运与队列同步固定开销为 $c$，请求到达率为 $\\lambda$。静态批处理下，两阶段串行执行，单请求驻留时间近似 $t_s+t_v$，但阶段切换时 GPU 存在空转比例 $\\epsilon$；解耦后驻留时间近似 $\\max(t_s,t_v)+c$（两阶段流水重叠），但每个请求多付 $c$。解耦划算的粗略条件是：</p>\n<div class=\"formula\">$$\\lambda\\cdot\\big[\\epsilon\\,(t_s+t_v)\\big] \\;&gt;\\; \\lambda\\cdot c \\quad\\Longleftrightarrow\\quad \\epsilon\\,(t_s+t_v) &gt; c$$</div>\n<p>即空转节省的时间必须超过搬运开销。$\\epsilon$ 随请求异构度上升——分辨率、时长、步数差异越大，静态批里\"等最慢的那个\"越严重，$\\epsilon$ 越大；$c$ 则随请求变短而相对变重，因为 $c$ 是固定成本而 $t_s,t_v$ 随请求缩小。这就精确解释了适用边界里\"极短请求或极低并发下固定开销可能超过收益\"：短请求让 $t_s+t_v$ 变小，$c$ 不变，不等式右侧相对变大。工程上不必精确测 $\\epsilon$，只需在两个极端负载下各跑一次：全同构短请求（$\\epsilon$ 小）与高度异构混合请求（$\\epsilon$ 大），比较端到端吞吐，若后者不升反降，说明 $c$ 已经吃掉收益，应退回静态批或加大批内请求的最小粒度。</p>\n<p>紧迫度排序本身也有代价。$u_i=(d_i-\\hat{t}_i^{\\text{rem}})/\\hat{t}_i^{\\text{rem}}$ 中 $\\hat{t}_i^{\\text{rem}}$ 是画像给出的估计，其误差 $\\delta$ 会直接传导入排序：两个请求的真实紧迫度差小于 $\\delta$ 引起的扰动时，排序等价于随机。因此调度器不应追求精细排序，而应按 $u_i$ 分桶（如紧迫/正常/宽松三档），桶内按到达顺序，桶间按档位——这既降低排序开销，也让画像误差不至于翻转决策。这与降级阶梯的粗粒度是同一设计哲学：粗粒度换稳定。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-50\">五十 · 与预填解码分离的取舍：切在哪里</h3>\n<p>预填解码分离与本条目同属调度层，二选一时看切分点是否与资源特征的真实断层对齐。LLM 中 prefill 是算力密集、decode 是带宽密集，断层在算术强度，切分后两阶段可配不同并行度甚至不同卡型。视频生成中 DiT 采样与 VAE 解码的断层不在算术强度，而在批处理语义：采样是迭代式的，步与步之间有天然插入点，适合连续批处理；VAE 解码是一次性前向产出多帧，没有步间插入点，只能靠微批并行摊薄单帧等待。因此本条目切出的两个队列不是\"两种算力\"，而是\"两种批处理节奏\"。这带来一个预填解码分离没有的问题：VAE 队列没有步间插入点，一旦积压就只能靠增加并行度或降级释放，弹性比采样队列差。诊断上表现为采样阶段利用率高而 VAE 队列深度持续上升——这正是失败模式里\"latent 队列积压使 VAE 成为瓶颈而采样空转\"的机制来源。对策不是加大采样批，而是给 VAE 阶段预留独立的显存与 SM 配额，使两阶段的资源配比可独立调整，这也是部署配方中\"采样与 VAE 分配不同卡组或不同并行轴\"的理由。</p>\n<p>若系统同时服务 LLM 与视频生成（agent 原生调度场景，对应 paper-sol-video-inference-engine-agent-nat-2026 那条线），则两层切分可以共存：LLM 侧用预填解码分离，视频侧用采样/VAE 解耦，两者共享同一个准入控制与降级框架，但画像表必须分开维护。混用一张画像表是跨模型未重标定的典型形态，会让视频请求的 $\\hat{t}^{\\text{rem}}$ 被 LLM 的标定污染。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-51\">五十一 · 与请求内算法的组合顺序</h3>\n<p>组合不是随便叠。正确的顺序是先定调度层骨架，再逐个替换内核层实现，每替换一个就重标定画像。理由是调度器的所有决策——批上限、紧迫度、降级阶梯——都读画像表，而画像表是内核层算法的函数。以量化为例：启用 NVFP4 后单请求显存下降，批上限本应上升，若画像表未更新，调度器仍按旧上限组批，量化带来的吞吐收益被调度器吃掉一半。以少步蒸馏为例：步数从多步降到少步后，降级阶梯里的\"减步\"档位可能已经低于蒸馏模型的下限，触发降级反而生成质量崩塌，此时应把降级阶梯改为\"降分辨率/跳帧\"优先。</p>\n<p>有一个组合需要特别小心：轨迹感知缓存复用与紧迫度排序。缓存命中使 $\\hat{t}^{\\text{rem}}$ 依赖请求历史，同一请求在不同时刻的剩余时间估计差异很大，若调度器用均值画像，会把命中率高的请求估得偏慢、排得偏后，实际它最快完成。可行做法是画像按\"冷/热\"两档维护，请求首次入队用冷档，缓存建立后切热档，并在 $u_i$ 计算中对热档请求乘一个小于 1 的修正因子。这是把请求内状态反馈到调度层的唯一必要通道，也是本条目与请求内算法耦合最深的地方。</p>\n\n<h3 id=\"alg-streaming-serving-slo-sec-52\">五十二 · 规模上限与重标定触发条件</h3>\n<p>本条目的规模上限由两件事决定：画像标定精度与队列内存。队列内存是硬上限——latent 队列里每个等待 VAE 的请求都占一份 latent 显存，队列深度乘以单请求 latent 大小就是不可压缩的底噪，它挤占的正是采样批的显存预算。因此队列深度上限必须与批上限联合设定，而不是各自独立。标定精度是软上限：$\\hat{t}^{\\text{rem}}$ 的相对误差随并发上升而放大（因为画像通常在低并发下标定，高并发下显存争用、HBM 带宽共享都会改变实际耗时），误差超过紧迫度分桶宽度时，分桶退化为随机，SLO 满足率下降。</p>\n<p>重标定的触发条件应写成可执行的规则而非感觉：更换模型结构、更换 Blackwell SKU（B200 与 B300、GB200 与 GB300 NVL72 的显存与带宽档位不同）、启用或关闭任一内核层算法、量化精度变更、并发量级跨越一个数量级——五者任一发生即重标定。重标定的最小产物是一张表：在若干代表性请求形态（分辨率×时长×步数）下，采样每步耗时、VAE 每帧耗时、单请求显存峰值、latent 搬运开销 $c$。有了这四列，$u_i$ 与批上限就能算，降级阶梯的档位阈值也能定。缺任何一列，调度器就在猜，而猜的代价直接体现为 SLO 违约沿队列连锁扩散——这是本条目最贵的一类故障，因为它的根因不在运行时而在标定阶段。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 自回归视频服务与投机解码</td></tr><tr><td>解决什么</td><td>流式视频生成服务需在SLO（首帧时延、帧间隔、端到端时长）下同时服务多请求，DiT采样与VAE解码阶段资源特征不同，静…</td></tr><tr><td>一句话机制</td><td>把请求拆成采样阶段与VAE解码阶段分别排队，按SLO紧迫度与显存预算做动态批组合与阶段流水，采样用连续批处理、VAE用…</td></tr><tr><td>代价与失效</td><td>两阶段队列与latent搬运增加显存与同步开销，短请求下调度开销占比高。；SLO估算依赖模型/硬件画像，跨模型或跨Blackwell SK…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-streaming-serving-slo · 共 8 个片段</p>\n";break;}}})();
